pub mod fdd_job__ {
    use crate::fdd_runtime::*;
    use crate::fdd_verify;

    pub fn sign_in(request: Value) -> Res<Value> {
        let __f = fdd_verify::frame("bp-auth-login");
        __f.enter("NODE-AUTH-LOGIN-001")?;
        let email = get(&get(&request, "body"), "email");
        let email_check = check_email(&email, &s("email"));
        let password = get(&get(&request, "body"), "password");
        __f.enter("NODE-AUTH-LOGIN-006")?;
        if !(is_true(&get(&email_check, "valid")) && !is_empty(&password)) {
            __f.enter("NODE-AUTH-LOGIN-009")?;
            return Ok(obj(vec![
                ("status", n(401.0)),
                ("body", obj(vec![
                    ("error", if is_true(&get(&email_check, "valid")) { get(&check_required(&password, &s("password")), "message") } else { get(&email_check, "message") }),
                ])),
            ]));
        }
        __f.enter("NODE-AUTH-LOGIN-010")?;
        let look_up_user = fdd_verify::dep("userService", "getUsersByEmail", "NODE-AUTH-LOGIN-010", vec![obj(vec![("query", omit_nulls(&obj(vec![("email", email.clone())])))])])?;
        let status1 = get(&look_up_user, "status");
        if eq(&status1, &n(200.0)) {
            __f.enter("NODE-AUTH-LOGIN-014")?;
            if !eq(&get(&get(&look_up_user, "body"), "passwordHash"), &format(&s("hash:{password}"), &obj(vec![("password", password.clone())]))) {
                __f.enter("NODE-AUTH-LOGIN-021")?;
                return Ok(obj(vec![("status", n(401.0)), ("body", obj(vec![("error", s("Invalid credentials"))]))]));
            }
            let id = get(&get(&look_up_user, "body"), "id");
            __f.enter("NODE-AUTH-LOGIN-018")?;
            let _ = fdd_verify::dep("eventBus", "publishUserLoggedIn", "NODE-AUTH-LOGIN-018", vec![obj(vec![("userId", id.clone())])])?;
            __f.enter("NODE-AUTH-LOGIN-019")?;
            return Ok(obj(vec![
                ("status", n(200.0)),
                ("body", obj(vec![
                    ("accessToken", format(&s("TEST-TOKEN-{id}"), &obj(vec![("id", id.clone())]))),
                    ("refreshToken", s("REFRESH-TOKEN")),
                    ("expiresIn", n(3600.0)),
                    ("tokenType", s("Bearer")),
                ])),
            ]));
        } else if eq(&status1, &n(404.0)) {
            __f.enter("NODE-AUTH-LOGIN-022")?;
            return Ok(obj(vec![("status", n(401.0)), ("body", obj(vec![("error", s("Invalid credentials"))]))]));
        } else {
            __f.enter("NODE-AUTH-LOGIN-023")?;
            return Err(fail(&s("UPSTREAM_ERROR"), &s("User Service failed")));
        }
    }
}

