// Runtime for code generated by Rabbinatix from Logic Blueprints. Do not edit: it is regenerated on export.
// Every helper mirrors the simulator, so generated handlers behave exactly like their blueprints.
#![allow(dead_code, unused_macros, unused_imports, clippy::all)]

use std::cell::Cell;
use std::collections::hash_map::RandomState;
use std::hash::{BuildHasher, Hasher};
use std::sync::Arc;
use std::time::{SystemTime, UNIX_EPOCH};

/// Text as JavaScript holds it: UTF-16 units (a lone surrogate stays as it is).
pub type Str = Arc<[u16]>;

/// A JSON value. Lists and objects are shared like JavaScript's; nothing changes one in place.
#[derive(Clone, Debug)]
pub enum Value {
    Null,
    Bool(bool),
    Num(f64),
    Str(Str),
    List(Arc<Vec<Value>>),
    Obj(Arc<Object>),
}

/// An object: its fields in the order they were set.
#[derive(Clone, Debug, Default)]
pub struct Object {
    entries: Vec<(Str, Value)>,
}

impl Object {
    pub fn get(&self, k: &[u16]) -> Option<&Value> {
        self.entries.iter().find(|(x, _)| &x[..] == k).map(|(_, v)| v)
    }
    pub fn has(&self, k: &[u16]) -> bool {
        self.entries.iter().any(|(x, _)| &x[..] == k)
    }
    pub fn set(&mut self, k: Str, v: Value) {
        match self.entries.iter_mut().find(|(x, _)| x[..] == k[..]) {
            Some(e) => e.1 = v,
            None => self.entries.push((k, v)),
        }
    }
    pub fn remove(&mut self, k: &[u16]) {
        self.entries.retain(|(x, _)| &x[..] != k);
    }
    pub fn len(&self) -> usize {
        self.entries.len()
    }
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }
    /// the fields in the order they were set
    pub fn entries(&self) -> &[(Str, Value)] {
        &self.entries
    }
}

/// An error with a code, like the simulator's errors (Throw nodes, DIVIDE_BY_ZERO, INVALID_JSON...). A stop
/// error ends the handler: Try and Retry never catch it.
#[derive(Clone, Debug)]
pub struct FddError {
    pub code: Str,
    pub message: Str,
    pub stop: bool,
}

impl FddError {
    pub fn new(code: &str, message: &str) -> FddError {
        FddError { code: units(code).into(), message: units(message).into(), stop: false }
    }
    /// an error that Try and Retry never catch
    pub fn stop(message: &str) -> FddError {
        FddError { stop: true, ..FddError::new("STOPPED", message) }
    }
    pub fn code(&self) -> String {
        String::from_utf16_lossy(&self.code)
    }
    pub fn message(&self) -> String {
        String::from_utf16_lossy(&self.message)
    }
}

impl std::fmt::Display for FddError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.code(), self.message())
    }
}

impl std::error::Error for FddError {}

/// What a handler returns: its result, or the error it failed with.
pub type Res<T> = Result<T, FddError>;

/// In a Try or Retry block: the value of an Ok, or leave the block with the error.
macro_rules! tr {
    ($l:lifetime, $e:expr) => {
        match $e {
            Ok(v) => v,
            Err(e) => break $l Err(e),
        }
    };
}
pub(crate) use tr;

pub const NULL: Value = Value::Null;

impl Value {
    /// JSON text as a value (JSON.parse); fails with INVALID_JSON.
    pub fn parse(text: &str) -> Res<Value> {
        JsonReader { s: units(text), i: 0 }.document()
    }
    /// The value as JSON text (JSON.stringify).
    pub fn to_json(&self) -> String {
        String::from_utf16_lossy(&json_units(self))
    }
    pub fn is_null(&self) -> bool {
        matches!(self, Value::Null)
    }
}

impl From<&str> for Value {
    fn from(x: &str) -> Value {
        s(x)
    }
}
impl From<String> for Value {
    fn from(x: String) -> Value {
        s(&x)
    }
}
impl From<f64> for Value {
    fn from(x: f64) -> Value {
        Value::Num(x)
    }
}
impl From<i64> for Value {
    fn from(x: i64) -> Value {
        Value::Num(x as f64)
    }
}
impl From<i32> for Value {
    fn from(x: i32) -> Value {
        Value::Num(x as f64)
    }
}
impl From<bool> for Value {
    fn from(x: bool) -> Value {
        Value::Bool(x)
    }
}
impl<T: Into<Value>> From<Vec<T>> for Value {
    fn from(x: Vec<T>) -> Value {
        Value::List(Arc::new(x.into_iter().map(Into::into).collect()))
    }
}
impl<T: Into<Value>> From<Option<T>> for Value {
    fn from(x: Option<T>) -> Value {
        x.map_or(Value::Null, Into::into)
    }
}

// ---------- building values (the generated code) ----------

/// a string
pub fn s(x: &str) -> Value {
    Value::Str(units(x).into())
}
/// a string from UTF-16 units (one with a lone surrogate)
pub fn su(x: &[u16]) -> Value {
    Value::Str(x.into())
}
pub fn n(x: f64) -> Value {
    Value::Num(x)
}
pub fn b(x: bool) -> Value {
    Value::Bool(x)
}
pub fn list(items: Vec<Value>) -> Value {
    Value::List(Arc::new(items))
}
/// An object from (key, value) pairs.
pub fn obj(kv: Vec<(&str, Value)>) -> Value {
    let mut o = Object::default();
    for (k, v) in kv {
        o.set(units(k).into(), v);
    }
    Value::Obj(Arc::new(o))
}
/// An object from (key, value) pairs with owned keys.
pub fn obj_of(kv: Vec<(String, Value)>) -> Value {
    let mut o = Object::default();
    for (k, v) in kv {
        o.set(units(&k).into(), v);
    }
    Value::Obj(Arc::new(o))
}
fn obj_units(kv: Vec<(Str, Value)>) -> Value {
    let mut o = Object::default();
    for (k, v) in kv {
        o.set(k, v);
    }
    Value::Obj(Arc::new(o))
}

// ---------- reading values (the contract types) ----------

/// String(v), with nil as "".
pub fn text_of(v: &Value) -> String {
    String::from_utf16_lossy(&str_u(v))
}
/// A number (Number(v)).
pub fn num_of(v: &Value) -> f64 {
    to_num(v)
}
/// A whole number (not a number is 0).
pub fn int_of(v: &Value) -> i64 {
    to_number(v) as i64
}
pub fn bool_of(v: &Value) -> bool {
    is_true(v)
}
/// The items of a list ([] for anything else).
pub fn list_of(v: &Value) -> Vec<Value> {
    iter(v)
}
/// The fields of an object, in order ([] for anything else).
pub fn map_of(v: &Value) -> Vec<(String, Value)> {
    match v {
        Value::Obj(o) => o.entries.iter().map(|(k, x)| (String::from_utf16_lossy(k), x.clone())).collect(),
        _ => Vec::new(),
    }
}
/// None for null.
pub fn opt_of(v: &Value) -> Option<Value> {
    if v.is_null() { None } else { Some(v.clone()) }
}

// ---------- text as UTF-16 units ----------

fn units(x: &str) -> Vec<u16> {
    x.encode_utf16().collect()
}
fn text(u: &[u16]) -> String {
    String::from_utf16_lossy(u)
}
fn ustr(u: Vec<u16>) -> Value {
    Value::Str(u.into())
}
/// the position of a text in another, in UTF-16 units
fn unit_index(t: &[u16], x: &[u16]) -> Option<usize> {
    if x.is_empty() {
        return Some(0);
    }
    if x.len() > t.len() {
        return None;
    }
    (0..=t.len() - x.len()).find(|&i| &t[i..i + x.len()] == x)
}
/// UTF-8 bytes (a lone surrogate as U+FFFD, like TextEncoder)
fn utf8(u: &[u16]) -> Vec<u8> {
    text(u).into_bytes()
}

// ---------- the value model the generated code uses ----------

/// A condition: true only for true, else JavaScript truthiness.
pub fn is_true(v: &Value) -> bool {
    truthy(v)
}
/// A number operand.
pub fn num(v: &Value) -> f64 {
    to_num(v)
}
/// o.name, null-safe: null when o is null or has no such field.
pub fn get(o: &Value, name: &str) -> Value {
    key_of(o, &s(name))
}
/// o[key], null-safe.
pub fn item(o: &Value, k: &Value) -> Value {
    key_of(o, k)
}
/// a === b for strings, numbers, booleans and null (objects and lists: the same one).
pub fn eq(a: &Value, x: &Value) -> bool {
    match (a, x) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(p), Value::Bool(q)) => p == q,
        (Value::Num(p), Value::Num(q)) => p == q,
        (Value::Str(p), Value::Str(q)) => p[..] == q[..],
        (Value::List(p), Value::List(q)) => Arc::ptr_eq(p, q),
        (Value::Obj(p), Value::Obj(q)) => Arc::ptr_eq(p, q),
        _ => false,
    }
}
/// a % b (JavaScript's remainder: the sign of a).
pub fn modulo(a: f64, x: f64) -> f64 {
    a % x
}
/// The items of a list (for a For Each).
pub fn iter(v: &Value) -> Vec<Value> {
    match v {
        Value::List(l) => l.to_vec(),
        _ => Vec::new(),
    }
}
/// (index, item) of a list; the index is a number.
pub fn indexed(v: &Value) -> Vec<(f64, Value)> {
    iter(v).into_iter().enumerate().map(|(i, x)| (i as f64, x)).collect()
}
/// from, from + 1, ... while at most to.
pub fn range(from: f64, to: f64) -> impl Iterator<Item = f64> {
    let mut i = from;
    std::iter::from_fn(move || {
        if i <= to {
            i += 1.0;
            Some(i - 1.0)
        } else {
            None
        }
    })
}
/// from, from + 1, ... without end (the loop stops itself).
pub fn counting(from: f64) -> impl Iterator<Item = f64> {
    let mut i = from - 1.0;
    std::iter::from_fn(move || {
        i += 1.0;
        Some(i)
    })
}

pub fn map(items: &Value, mut f: impl FnMut(&Value, f64) -> Res<Value>) -> Res<Value> {
    let mut out = Vec::new();
    for (i, x) in as_list(items).iter().enumerate() {
        out.push(f(x, i as f64)?);
    }
    Ok(list(out))
}
pub fn filter(items: &Value, mut f: impl FnMut(&Value, f64) -> Res<bool>) -> Res<Value> {
    let mut out = Vec::new();
    for (i, x) in as_list(items).iter().enumerate() {
        if f(x, i as f64)? {
            out.push(x.clone());
        }
    }
    Ok(list(out))
}
pub fn find(items: &Value, mut f: impl FnMut(&Value, f64) -> Res<bool>) -> Res<Value> {
    for (i, x) in as_list(items).iter().enumerate() {
        if f(x, i as f64)? {
            return Ok(x.clone());
        }
    }
    Ok(NULL)
}
pub fn some(items: &Value, mut f: impl FnMut(&Value, f64) -> Res<bool>) -> Res<bool> {
    for (i, x) in as_list(items).iter().enumerate() {
        if f(x, i as f64)? {
            return Ok(true);
        }
    }
    Ok(false)
}
pub fn every(items: &Value, mut f: impl FnMut(&Value, f64) -> Res<bool>) -> Res<bool> {
    for (i, x) in as_list(items).iter().enumerate() {
        if !f(x, i as f64)? {
            return Ok(false);
        }
    }
    Ok(true)
}
/// One item at a time (deterministic order).
pub fn map_async(items: &Value, f: impl FnMut(&Value, f64) -> Res<Value>) -> Res<Value> {
    map(items, f)
}
pub fn filter_async(items: &Value, mut f: impl FnMut(&Value, f64) -> Res<Value>) -> Res<Value> {
    filter(items, |x, i| Ok(truthy(&f(x, i)?)))
}
pub fn find_async(items: &Value, mut f: impl FnMut(&Value, f64) -> Res<Value>) -> Res<Value> {
    find(items, |x, i| Ok(truthy(&f(x, i)?)))
}
pub fn some_async(items: &Value, mut f: impl FnMut(&Value, f64) -> Res<Value>) -> Res<bool> {
    some(items, |x, i| Ok(truthy(&f(x, i)?)))
}
pub fn every_async(items: &Value, mut f: impl FnMut(&Value, f64) -> Res<Value>) -> Res<bool> {
    every(items, |x, i| Ok(truthy(&f(x, i)?)))
}

fn key_of(o: &Value, k: &Value) -> Value {
    match o {
        Value::Obj(m) => {
            let key = match k {
                Value::Str(x) => x.to_vec(),
                _ => js_string(k),
            };
            m.get(&key).cloned().unwrap_or(NULL)
        }
        Value::List(l) => {
            if is_text(k, "length") {
                return n(l.len() as f64);
            }
            list_index(k).and_then(|i| l.get(i).cloned()).unwrap_or(NULL)
        }
        Value::Str(t) => {
            if is_text(k, "length") {
                return n(t.len() as f64);
            }
            list_index(k).and_then(|i| t.get(i).map(|c| ustr(vec![*c]))).unwrap_or(NULL)
        }
        _ => NULL,
    }
}
fn is_text(v: &Value, x: &str) -> bool {
    matches!(v, Value::Str(t) if t[..] == units(x)[..])
}
/// A list position.
fn list_index(k: &Value) -> Option<usize> {
    let d = match k {
        Value::Num(x) => *x,
        Value::Str(t) if !t.is_empty() && t.iter().all(|c| (0x30..=0x39).contains(c)) => text(t).parse::<f64>().ok()?,
        _ => return None,
    };
    if d >= 0.0 && d < 2_147_483_647.0 && d.floor() == d { Some(d as usize) } else { None }
}
fn trunc(d: f64) -> f64 {
    if d.is_finite() { d.trunc() } else { d }
}

// ---------- JavaScript conversions ----------

/// A number as JavaScript's String(n) writes it.
pub fn num_text(x: f64) -> String {
    if x.is_nan() {
        return "NaN".into();
    }
    if x.is_infinite() {
        return if x > 0.0 { "Infinity".into() } else { "-Infinity".into() };
    }
    if x == 0.0 {
        return "0".into();
    }
    // {:e} has the shortest digits that read back as the same number
    let e = format!("{:e}", x.abs());
    let (mant, exp) = e.split_once('e').unwrap();
    let digits: String = mant.chars().filter(|c| *c != '.').collect();
    let k = digits.len() as i32;
    let point = exp.parse::<i32>().unwrap() + 1;
    let sign = if x < 0.0 { "-" } else { "" };
    if k <= point && point <= 21 {
        return format!("{}{}{}", sign, digits, "0".repeat((point - k) as usize));
    }
    if 0 < point && point <= 21 {
        return format!("{}{}.{}", sign, &digits[..point as usize], &digits[point as usize..]);
    }
    if -6 < point && point <= 0 {
        return format!("{}0.{}{}", sign, "0".repeat((-point) as usize), digits);
    }
    let p = point - 1;
    let rest = if k > 1 { format!(".{}", &digits[1..]) } else { String::new() };
    format!("{}{}{}e{}{}", sign, &digits[..1], rest, if p >= 0 { "+" } else { "-" }, p.abs())
}

/// String(v), as UTF-16 units.
fn js_string(v: &Value) -> Vec<u16> {
    match v {
        Value::Null => units("null"),
        Value::Bool(x) => units(if *x { "true" } else { "false" }),
        Value::Num(x) => units(&num_text(*x)),
        Value::Str(t) => t.to_vec(),
        Value::List(l) => {
            let mut out = Vec::new();
            for (i, x) in l.iter().enumerate() {
                if i > 0 {
                    out.push(0x2c);
                }
                if !x.is_null() {
                    out.extend(js_string(x));
                }
            }
            out
        }
        Value::Obj(_) => units("[object Object]"),
    }
}

/// JSON.stringify, as UTF-16 units.
fn json_units(v: &Value) -> Vec<u16> {
    let mut out = Vec::new();
    write_json(v, &mut out);
    out
}
fn write_json(v: &Value, out: &mut Vec<u16>) {
    match v {
        Value::Null => out.extend(units("null")),
        Value::Bool(_) => out.extend(js_string(v)),
        Value::Num(x) => out.extend(units(&if x.is_finite() { num_text(*x) } else { "null".into() })),
        Value::Str(t) => quote(t, out),
        Value::List(l) => {
            out.push(0x5b);
            for (i, x) in l.iter().enumerate() {
                if i > 0 {
                    out.push(0x2c);
                }
                write_json(x, out);
            }
            out.push(0x5d);
        }
        Value::Obj(o) => {
            out.push(0x7b);
            for (i, k) in key_list(o).iter().enumerate() {
                if i > 0 {
                    out.push(0x2c);
                }
                quote(k, out);
                out.push(0x3a);
                write_json(o.get(k).unwrap(), out);
            }
            out.push(0x7d);
        }
    }
}
fn quote(u: &[u16], out: &mut Vec<u16>) {
    out.push(0x22);
    let mut i = 0;
    while i < u.len() {
        let c = u[i];
        let esc = match c {
            0x22 => Some("\\\""),
            0x5c => Some("\\\\"),
            0x0a => Some("\\n"),
            0x0d => Some("\\r"),
            0x09 => Some("\\t"),
            0x08 => Some("\\b"),
            0x0c => Some("\\f"),
            _ => None,
        };
        if let Some(e) = esc {
            out.extend(units(e));
        } else if c < 0x20 {
            out.extend(units(&format!("\\u{:04x}", c)));
        } else if (0xd800..=0xdbff).contains(&c) && i + 1 < u.len() && (0xdc00..=0xdfff).contains(&u[i + 1]) {
            out.push(c);
            out.push(u[i + 1]);
            i += 1;
        } else if (0xd800..=0xdfff).contains(&c) {
            out.extend(units(&format!("\\u{:04x}", c)));
        } else {
            out.push(c);
        }
        i += 1;
    }
    out.push(0x22);
}

/// JavaScript's white space and line terminators (what String.prototype.trim removes).
fn js_space(c: u16) -> bool {
    matches!(c, 0x09..=0x0d | 0x20 | 0xa0 | 0x1680 | 0x2000..=0x200a | 0x2028 | 0x2029 | 0x202f | 0x205f | 0x3000 | 0xfeff)
}
fn js_trim(u: &[u16]) -> &[u16] {
    let a = u.iter().position(|c| !js_space(*c)).unwrap_or(u.len());
    let z = u.iter().rposition(|c| !js_space(*c)).map_or(a, |i| i + 1);
    &u[a..z.max(a)]
}

/// Number(v).
fn js_number(v: &Value) -> f64 {
    match v {
        Value::Null => 0.0,
        Value::Bool(x) => if *x { 1.0 } else { 0.0 },
        Value::Num(x) => *x,
        Value::Str(t) => text_number(&text(js_trim(t))),
        Value::List(l) => match l.len() {
            0 => 0.0,
            1 => match &l[0] {
                Value::List(_) | Value::Obj(_) => f64::NAN,
                Value::Null => 0.0,
                x => js_number(&ustr(js_string(x))),
            },
            _ => f64::NAN,
        },
        Value::Obj(_) => f64::NAN,
    }
}
fn text_number(t: &str) -> f64 {
    if t.is_empty() {
        return 0.0;
    }
    let lower = t.to_ascii_lowercase();
    for (p, radix) in [("0x", 16), ("0o", 8), ("0b", 2)] {
        if let Some(rest) = lower.strip_prefix(p) {
            if rest.is_empty() || !rest.chars().all(|c| c.is_digit(radix)) {
                return f64::NAN;
            }
            return rest.chars().fold(0.0, |a, c| a * radix as f64 + c.to_digit(radix).unwrap() as f64);
        }
    }
    match t {
        "Infinity" | "+Infinity" => return f64::INFINITY,
        "-Infinity" => return f64::NEG_INFINITY,
        _ => {}
    }
    // [+-]? (digits [. digits*] | . digits) ([eE] [+-]? digits)?
    let c: Vec<char> = t.chars().collect();
    let mut i = 0;
    if i < c.len() && (c[i] == '+' || c[i] == '-') {
        i += 1;
    }
    let int = c[i..].iter().take_while(|x| x.is_ascii_digit()).count();
    i += int;
    let mut frac = 0;
    if i < c.len() && c[i] == '.' {
        i += 1;
        frac = c[i..].iter().take_while(|x| x.is_ascii_digit()).count();
        i += frac;
    }
    if int + frac == 0 {
        return f64::NAN;
    }
    if i < c.len() && (c[i] == 'e' || c[i] == 'E') {
        i += 1;
        if i < c.len() && (c[i] == '+' || c[i] == '-') {
            i += 1;
        }
        let e = c[i..].iter().take_while(|x| x.is_ascii_digit()).count();
        if e == 0 {
            return f64::NAN;
        }
        i += e;
    }
    if i != c.len() {
        return f64::NAN;
    }
    t.parse::<f64>().unwrap_or(f64::NAN)
}

fn prim(x: &Value) -> Value {
    match x {
        Value::List(_) | Value::Obj(_) => ustr(js_string(x)),
        _ => x.clone(),
    }
}
fn lt(a: &Value, x: &Value) -> bool {
    if let (Value::Str(p), Value::Str(q)) = (a, x) {
        return p[..] < q[..];
    }
    js_number(&prim(a)) < js_number(&prim(x))
}

// ---------- values ----------

/// Branch semantics: "" and "false" are false.
pub fn truthy(v: &Value) -> bool {
    match v {
        Value::Null => false,
        Value::Bool(x) => *x,
        Value::Num(x) => *x != 0.0 && !x.is_nan(),
        Value::Str(t) => !t.is_empty() && t[..] != units("false")[..],
        _ => true,
    }
}
/// null, "", [] or {}.
pub fn is_empty(v: &Value) -> bool {
    match v {
        Value::Null => true,
        Value::Str(t) => js_trim(t).is_empty(),
        Value::List(l) => l.is_empty(),
        Value::Obj(o) => o.is_empty(),
        _ => false,
    }
}
pub fn is_null(v: &Value) -> bool {
    v.is_null()
}
/// Structural equality (objects and arrays by value).
pub fn deep_equal(a: &Value, x: &Value) -> bool {
    match (a, x) {
        (Value::Num(p), Value::Num(q)) => p == q || (p.is_nan() && q.is_nan()),
        (Value::List(p), Value::List(q)) => p.len() == q.len() && p.iter().zip(q.iter()).all(|(u, w)| deep_equal(u, w)),
        (Value::Obj(p), Value::Obj(q)) => p.len() == q.len() && p.entries.iter().all(|(k, u)| q.get(k).is_some_and(|w| deep_equal(u, w))),
        _ => eq(a, x),
    }
}
/// -1, 0 or 1.
pub fn compare(a: &Value, x: &Value) -> f64 {
    if deep_equal(a, x) {
        0.0
    } else if lt(a, x) {
        -1.0
    } else {
        1.0
    }
}
/// An arithmetic operand: numbers as is, anything else through Number().
pub fn to_num(v: &Value) -> f64 {
    js_number(v)
}
/// Fails on zero.
pub fn divide(a: &Value, x: &Value) -> Res<f64> {
    if to_num(x) == 0.0 {
        return Err(FddError::new("DIVIDE_BY_ZERO", "Division by zero"));
    }
    Ok(to_num(a) / to_num(x))
}
fn as_list(v: &Value) -> Arc<Vec<Value>> {
    match v {
        Value::List(l) => l.clone(),
        _ => Arc::new(Vec::new()),
    }
}
/// The value if it is a list, else [].
pub fn as_array(v: &Value) -> Value {
    match v {
        Value::List(_) => v.clone(),
        _ => list(Vec::new()),
    }
}
/// A query found something (not null, not an empty list).
pub fn is_found(v: &Value) -> bool {
    match v {
        Value::List(l) => !l.is_empty(),
        _ => !v.is_null(),
    }
}
/// Drops null entries (query and header maps).
pub fn omit_nulls(o: &Value) -> Value {
    match o {
        Value::Obj(m) => obj_units(key_list(m).into_iter().filter_map(|k| m.get(&k).filter(|x| !x.is_null()).map(|x| (Str::from(k.clone()), x.clone()))).collect()),
        _ => obj(vec![]),
    }
}

// ---------- paths & objects ----------

#[derive(Clone)]
enum Seg {
    Name(Vec<u16>),
    Index(usize),
}
impl Seg {
    fn key(&self) -> Vec<u16> {
        match self {
            Seg::Name(x) => x.clone(),
            Seg::Index(i) => units(&i.to_string()),
        }
    }
}
/// user.roles[0].name → Name(user), Name(roles), Index(0), Name(name)
fn segments(path: &[u16]) -> Vec<Seg> {
    let mut out = Vec::new();
    for part in path.split(|c| *c == 0x2e) {
        let mut i = 0;
        while i < part.len() {
            let c = part[i];
            if c != 0x5b && c != 0x5d {
                let j = part[i..].iter().position(|x| *x == 0x5b || *x == 0x5d).map_or(part.len(), |p| i + p);
                out.push(Seg::Name(part[i..j].to_vec()));
                i = j;
                continue;
            }
            if c == 0x5b {
                let d = part[i + 1..].iter().take_while(|x| (0x30..=0x39).contains(*x)).count();
                if d > 0 && part.get(i + 1 + d) == Some(&0x5d) {
                    let digits = text(&part[i + 1..i + 1 + d]);
                    out.push(Seg::Index(if d > 9 { 2_147_483_647 } else { digits.parse().unwrap() }));
                    i += d + 2;
                    continue;
                }
            }
            i += 1;
        }
    }
    out
}
fn unsafe_path(segs: &[Seg]) -> bool {
    segs.iter().any(|x| matches!(x, Seg::Name(k) if ["__proto__", "constructor", "prototype"].iter().any(|w| k[..] == units(w)[..])))
}
fn path_units(p: &Value) -> Vec<u16> {
    str_u(p)
}
/// The path exists (its value may be null).
pub fn has_path(value: &Value, path: &Value) -> bool {
    let p = path_units(path);
    if p.is_empty() || p[..] == [0x24] {
        return true;
    }
    let segs = segments(&p);
    if unsafe_path(&segs) {
        return false;
    }
    let mut cur = value.clone();
    for x in &segs {
        cur = match &cur {
            Value::Obj(o) => match o.get(&x.key()) {
                Some(v) => v.clone(),
                None => return false,
            },
            Value::List(_) | Value::Str(_) => {
                let len = match &cur {
                    Value::List(l) => l.len(),
                    Value::Str(t) => t.len(),
                    _ => 0,
                };
                match x {
                    Seg::Name(k) if k[..] == units("length")[..] => n(len as f64),
                    Seg::Index(i) if *i < len => key_of(&cur, &n(*i as f64)),
                    _ => return false,
                }
            }
            _ => return false,
        };
    }
    true
}
/// Reads a nested value; null when a step is missing.
pub fn get_path(value: &Value, path: &Value) -> Value {
    let p = path_units(path);
    if p.is_empty() || p[..] == [0x24] {
        return value.clone();
    }
    let segs = segments(&p);
    if unsafe_path(&segs) {
        return NULL;
    }
    let mut cur = value.clone();
    for x in &segs {
        if cur.is_null() {
            return NULL;
        }
        cur = match x {
            Seg::Name(k) => key_of(&cur, &ustr(k.clone())),
            Seg::Index(i) => key_of(&cur, &n(*i as f64)),
        };
    }
    cur
}
/// a path's value, or None (JavaScript's undefined) when the path isn't there
fn lookup(value: &Value, path: &[u16]) -> Option<Value> {
    let p = ustr(path.to_vec());
    if has_path(value, &p) { Some(get_path(value, &p)) } else { None }
}
fn container(v: &Value) -> bool {
    matches!(v, Value::List(_) | Value::Obj(_))
}
/// A copy with a nested value set.
pub fn set_path(value: &Value, path: &Value, v: &Value) -> Value {
    set_opt(value, &path_units(path), Some(v.clone()))
}
fn set_opt(value: &Value, path: &[u16], v: Option<Value>) -> Value {
    let segs = segments(path);
    if segs.is_empty() {
        return v.unwrap_or(NULL);
    }
    let root = if container(value) { value.clone() } else { obj(vec![]) };
    if unsafe_path(&segs) {
        return root;
    }
    set_in(&root, &segs, 0, v)
}
/// cur (a container) with segs[i..] set: a fresh copy
fn set_in(cur: &Value, segs: &[Seg], i: usize, v: Option<Value>) -> Value {
    let last = i == segs.len() - 1;
    let next = |old: Option<&Value>| -> Value {
        match old {
            Some(x) if container(x) => x.clone(),
            _ => match segs[i + 1] {
                Seg::Index(_) => list(vec![]),
                Seg::Name(_) => obj(vec![]),
            },
        }
    };
    match cur {
        Value::List(l) => {
            let at = match segs[i] {
                Seg::Index(x) => x,
                Seg::Name(_) => return cur.clone(),
            };
            let mut items = l.to_vec();
            while items.len() <= at {
                items.push(NULL);
            }
            if last {
                if let Some(x) = v {
                    items[at] = x;
                }
            } else {
                let nx = next(Some(&items[at]));
                items[at] = set_in(&nx, segs, i + 1, v);
            }
            list(items)
        }
        Value::Obj(o) => {
            let k: Str = segs[i].key().into();
            let mut m = (**o).clone();
            if last {
                if let Some(x) = v {
                    m.set(k, x);
                }
            } else {
                let nx = next(o.get(&k));
                m.set(k, set_in(&nx, segs, i + 1, v));
            }
            Value::Obj(Arc::new(m))
        }
        _ => cur.clone(),
    }
}
/// A copy without a nested value.
pub fn remove_path(value: &Value, path: &Value) -> Value {
    let segs = segments(&path_units(path));
    if segs.is_empty() || !container(value) || unsafe_path(&segs) {
        return value.clone();
    }
    remove_in(value, &segs, 0)
}
fn remove_in(cur: &Value, segs: &[Seg], i: usize) -> Value {
    let x = &segs[i];
    let last = i == segs.len() - 1;
    match cur {
        Value::List(l) => {
            let at = match x {
                Seg::Index(a) if *a < l.len() => *a,
                _ => return cur.clone(),
            };
            let mut items = l.to_vec();
            if last {
                items.remove(at);
            } else if container(&items[at]) {
                items[at] = remove_in(&items[at], segs, i + 1);
            }
            list(items)
        }
        Value::Obj(o) => {
            let k = x.key();
            let mut m = (**o).clone();
            if last {
                m.remove(&k);
            } else if let Some(nx) = o.get(&k).filter(|v| container(v)) {
                m.set(k.into(), remove_in(nx, segs, i + 1));
            }
            Value::Obj(Arc::new(m))
        }
        _ => cur.clone(),
    }
}
fn spread(v: &Value) -> Vec<(Str, Value)> {
    match v {
        Value::Obj(o) => o.entries.clone(),
        Value::List(l) => l.iter().enumerate().map(|(i, x)| (Str::from(units(&i.to_string())), x.clone())).collect(),
        Value::Str(t) => t.iter().enumerate().map(|(i, c)| (Str::from(units(&i.to_string())), ustr(vec![*c]))).collect(),
        _ => Vec::new(),
    }
}
/// Shallow merge, B over A.
pub fn merge(a: &Value, x: &Value) -> Value {
    let mut all = spread(a);
    all.extend(spread(x));
    obj_units(all)
}
/// A new object: target path from source path.
pub fn transform(source: &Value, mapping: &Value) -> Value {
    let mut out = obj(vec![]);
    for pair in as_list(mapping).iter() {
        let p = as_list(pair);
        let target = path_units(p.first().unwrap_or(&NULL));
        let from = str_u(p.get(1).unwrap_or(&NULL));
        out = set_opt(&out, &target, lookup(source, &from));
    }
    out
}
/// Fills {{path}} placeholders from data.
pub fn template(value: &Value, data: &Value) -> Value {
    fill(value, data).unwrap_or(NULL)
}
/// the path of a whole {{ path }} placeholder, or of each one in a text: (start, end, path)
fn placeholders(t: &[u16]) -> Vec<(usize, usize, Vec<u16>)> {
    let mut out = Vec::new();
    let mut i = 0;
    while i + 1 < t.len() {
        if t[i] == 0x7b && t[i + 1] == 0x7b {
            // {{\s*([^}]+?)\s*}}
            let start = i;
            let mut j = i + 2;
            while j < t.len() && t[j] != 0x7d {
                j += 1;
            }
            if j + 1 < t.len() && t[j + 1] == 0x7d && j > i + 2 {
                let inner = &t[i + 2..j];
                let a = inner.iter().position(|c| !js_space(*c)).unwrap_or(inner.len());
                let z = inner.iter().rposition(|c| !js_space(*c)).map_or(a, |p| p + 1);
                if z > a {
                    out.push((start, j + 2, inner[a..z].to_vec()));
                    i = j + 2;
                    continue;
                }
            }
        }
        i += 1;
    }
    out
}
fn fill(value: &Value, data: &Value) -> Option<Value> {
    match value {
        Value::Str(t) => {
            let ps = placeholders(t);
            if ps.len() == 1 && ps[0].0 == 0 && ps[0].1 == t.len() {
                return lookup(data, &ps[0].2);
            }
            let mut out = Vec::new();
            let mut at = 0;
            for (a, z, p) in ps {
                out.extend_from_slice(&t[at..a]);
                let r = get_path(data, &ustr(p));
                if !r.is_null() {
                    out.extend(if container(&r) { json_units(&r) } else { js_string(&r) });
                }
                at = z;
            }
            out.extend_from_slice(&t[at..]);
            Some(ustr(out))
        }
        Value::List(l) => Some(list(l.iter().map(|x| fill(x, data).unwrap_or(NULL)).collect())),
        Value::Obj(o) => Some(obj_units(o.entries.iter().filter_map(|(k, x)| fill(x, data).map(|z| (k.clone(), z))).collect())),
        _ => Some(value.clone()),
    }
}
/// JSON.parse that fails with INVALID_JSON.
pub fn parse_json(t: &Value) -> Res<Value> {
    JsonReader { s: js_string(t), i: 0 }.document()
}
/// The { code, message } a Catch or Failed pin receives; a stop error goes on.
pub fn to_error(e: FddError) -> Res<Value> {
    if e.stop {
        return Err(e);
    }
    Ok(obj(vec![("code", Value::Str(e.code)), ("message", Value::Str(e.message))]))
}
/// A Throw's error.
pub fn fail(code: &Value, message: &Value) -> FddError {
    FddError { code: js_string(code).into(), message: js_string(message).into(), stop: false }
}

/// Strict JSON (what JSON.parse accepts).
struct JsonReader {
    s: Vec<u16>,
    i: usize,
}
impl JsonReader {
    fn bad() -> FddError {
        FddError::new("INVALID_JSON", "Not valid JSON")
    }
    fn ws(&mut self) {
        while self.i < self.s.len() && matches!(self.s[self.i], 0x20 | 0x09 | 0x0a | 0x0d) {
            self.i += 1;
        }
    }
    fn peek(&self) -> Res<u16> {
        self.s.get(self.i).copied().ok_or_else(Self::bad)
    }
    fn document(&mut self) -> Res<Value> {
        self.ws();
        let v = self.value(0)?;
        self.ws();
        if self.i != self.s.len() {
            return Err(Self::bad());
        }
        Ok(v)
    }
    fn word(&mut self, w: &str) -> bool {
        let u = units(w);
        if self.s.len() >= self.i + u.len() && self.s[self.i..self.i + u.len()] == u[..] {
            self.i += u.len();
            true
        } else {
            false
        }
    }
    fn value(&mut self, depth: usize) -> Res<Value> {
        if depth > 5000 {
            return Err(Self::bad());
        }
        match self.peek()? {
            0x7b => self.object(depth),
            0x5b => self.array(depth),
            0x22 => Ok(ustr(self.string()?)),
            _ => {
                if self.word("true") {
                    return Ok(b(true));
                }
                if self.word("false") {
                    return Ok(b(false));
                }
                if self.word("null") {
                    return Ok(NULL);
                }
                self.number()
            }
        }
    }
    fn digits(&mut self) -> usize {
        let a = self.i;
        while self.i < self.s.len() && (0x30..=0x39).contains(&self.s[self.i]) {
            self.i += 1;
        }
        self.i - a
    }
    fn number(&mut self) -> Res<Value> {
        let a = self.i;
        if self.s.get(self.i) == Some(&0x2d) {
            self.i += 1;
        }
        let int_start = self.i;
        let d = self.digits();
        if d == 0 || (d > 1 && self.s[int_start] == 0x30) {
            return Err(Self::bad());
        }
        if self.s.get(self.i) == Some(&0x2e) {
            self.i += 1;
            if self.digits() == 0 {
                return Err(Self::bad());
            }
        }
        if matches!(self.s.get(self.i), Some(0x65) | Some(0x45)) {
            self.i += 1;
            if matches!(self.s.get(self.i), Some(0x2b) | Some(0x2d)) {
                self.i += 1;
            }
            if self.digits() == 0 {
                return Err(Self::bad());
            }
        }
        text(&self.s[a..self.i]).parse::<f64>().map(n).map_err(|_| Self::bad())
    }
    fn object(&mut self, depth: usize) -> Res<Value> {
        let mut o = Object::default();
        self.i += 1;
        self.ws();
        if self.peek()? == 0x7d {
            self.i += 1;
            return Ok(Value::Obj(Arc::new(o)));
        }
        loop {
            self.ws();
            if self.peek()? != 0x22 {
                return Err(Self::bad());
            }
            let k = self.string()?;
            self.ws();
            if self.peek()? != 0x3a {
                return Err(Self::bad());
            }
            self.i += 1;
            self.ws();
            let v = self.value(depth + 1)?;
            o.set(k.into(), v);
            self.ws();
            let c = self.peek()?;
            self.i += 1;
            if c == 0x7d {
                return Ok(Value::Obj(Arc::new(o)));
            }
            if c != 0x2c {
                return Err(Self::bad());
            }
        }
    }
    fn array(&mut self, depth: usize) -> Res<Value> {
        let mut l = Vec::new();
        self.i += 1;
        self.ws();
        if self.peek()? == 0x5d {
            self.i += 1;
            return Ok(list(l));
        }
        loop {
            self.ws();
            l.push(self.value(depth + 1)?);
            self.ws();
            let c = self.peek()?;
            self.i += 1;
            if c == 0x5d {
                return Ok(list(l));
            }
            if c != 0x2c {
                return Err(Self::bad());
            }
        }
    }
    fn string(&mut self) -> Res<Vec<u16>> {
        self.i += 1;
        let mut out = Vec::new();
        loop {
            let c = self.peek()?;
            self.i += 1;
            match c {
                0x22 => return Ok(out),
                0x00..=0x1f => return Err(Self::bad()),
                0x5c => {
                    let e = self.peek()?;
                    self.i += 1;
                    let simple = match e {
                        0x22 => Some(0x22),
                        0x5c => Some(0x5c),
                        0x2f => Some(0x2f),
                        0x62 => Some(0x08),
                        0x66 => Some(0x0c),
                        0x6e => Some(0x0a),
                        0x72 => Some(0x0d),
                        0x74 => Some(0x09),
                        _ => None,
                    };
                    if let Some(x) = simple {
                        out.push(x);
                        continue;
                    }
                    if e != 0x75 || self.s.len() < self.i + 4 {
                        return Err(Self::bad());
                    }
                    // \u escapes are UTF-16 units already
                    let hex = text(&self.s[self.i..self.i + 4]);
                    if !hex.chars().all(|x| x.is_ascii_hexdigit()) {
                        return Err(Self::bad());
                    }
                    out.push(u16::from_str_radix(&hex, 16).unwrap());
                    self.i += 4;
                }
                _ => out.push(c),
            }
        }
    }
}

// ---------- strings ----------

fn str_u(v: &Value) -> Vec<u16> {
    if v.is_null() { Vec::new() } else { js_string(v) }
}
/// A string operand: null is "".
pub fn str(v: &Value) -> Value {
    ustr(str_u(v))
}
/// String(v), like a Switch compares.
pub fn as_string(v: &Value) -> Value {
    ustr(js_string(v))
}
pub fn contains(t: &Value, x: &Value) -> bool {
    unit_index(&str_u(t), &str_u(x)).is_some()
}
pub fn starts_with(t: &Value, x: &Value) -> bool {
    str_u(t).starts_with(&str_u(x))
}
pub fn ends_with(t: &Value, x: &Value) -> bool {
    str_u(t).ends_with(&str_u(x))
}
pub fn trim(t: &Value) -> Value {
    ustr(js_trim(&str_u(t)).to_vec())
}
pub fn lower(t: &Value) -> Value {
    s(&text(&str_u(t)).to_lowercase())
}
pub fn upper(t: &Value) -> Value {
    s(&text(&str_u(t)).to_uppercase())
}
pub fn str_length(t: &Value) -> f64 {
    str_u(t).len() as f64
}
pub fn concat(a: &Value, x: &Value) -> Value {
    let mut u = str_u(a);
    u.extend(str_u(x));
    ustr(u)
}
/// text split on a separator (an empty one splits every UTF-16 unit, like JavaScript)
fn split_units(t: &[u16], sep: &[u16]) -> Vec<Vec<u16>> {
    if sep.is_empty() {
        return t.iter().map(|c| vec![*c]).collect();
    }
    let mut out = Vec::new();
    let mut at = 0;
    let mut i = 0;
    while i + sep.len() <= t.len() {
        if &t[i..i + sep.len()] == sep {
            out.push(t[at..i].to_vec());
            i += sep.len();
            at = i;
        } else {
            i += 1;
        }
    }
    out.push(t[at..].to_vec());
    out
}
fn join_units(parts: Vec<Vec<u16>>, sep: &[u16]) -> Vec<u16> {
    let mut out = Vec::new();
    for (i, p) in parts.into_iter().enumerate() {
        if i > 0 {
            out.extend_from_slice(sep);
        }
        out.extend(p);
    }
    out
}
pub fn replace_all(t: &Value, search: &Value, replacement: &Value) -> Value {
    ustr(join_units(split_units(&str_u(t), &str_u(search)), &str_u(replacement)))
}
/// An empty separator splits on ",".
pub fn split(t: &Value, separator: &Value) -> Value {
    let sep = str_u(separator);
    let sep = if sep.is_empty() { units(",") } else { sep };
    list(split_units(&str_u(t), &sep).into_iter().map(ustr).collect())
}
pub fn join(items: &Value, separator: &Value) -> Value {
    ustr(join_units(as_list(items).iter().map(str_u).collect(), &str_u(separator)))
}
pub fn regex_match(t: &Value, pattern: &Value, flags: &Value) -> Res<Value> {
    let f = text(&str_u(flags));
    let bad = || FddError { code: units("INVALID_REGEX").into(), message: [units("Invalid pattern "), str_u(pattern)].concat().into(), stop: false };
    if f.chars().any(|c| !"gimsuyd".contains(c)) {
        return Err(bad());
    }
    let re = Regex::new(&str_u(pattern), &f).map_err(|_| bad())?;
    Ok(match re.search(&str_u(t)) {
        Some(caps) => obj(vec![
            ("matches", b(true)),
            ("groups", list(caps[1..].iter().map(|c| c.map_or(NULL, |(a, z)| ustr(str_u(t)[a..z].to_vec()))).collect())),
        ]),
        None => obj(vec![("matches", b(false)), ("groups", list(vec![]))]),
    })
}
/// Fills {name} placeholders.
pub fn format(template: &Value, values: &Value) -> Value {
    let t = str_u(template);
    let word = |c: u16| matches!(c, 0x30..=0x39 | 0x41..=0x5a | 0x61..=0x7a | 0x5f);
    let mut out = Vec::new();
    let mut i = 0;
    while i < t.len() {
        if t[i] == 0x7b {
            let w = t[i + 1..].iter().take_while(|c| word(**c)).count();
            if w > 0 && t.get(i + 1 + w) == Some(&0x7d) {
                out.extend(str_u(&key_of(values, &ustr(t[i + 1..i + 1 + w].to_vec()))));
                i += w + 2;
                continue;
            }
        }
        out.push(t[i]);
        i += 1;
    }
    ustr(out)
}

// ---------- collections ----------

pub fn len(a: &Value) -> f64 {
    match a {
        Value::List(l) => l.len() as f64,
        _ => 0.0,
    }
}
pub fn at(a: &Value, i: &Value) -> Value {
    key_of(&as_array(a), &n(to_num(i)))
}
/// A copy with the item appended.
pub fn append(a: &Value, x: &Value) -> Value {
    let mut l = iter(a);
    l.push(x.clone());
    list(l)
}
/// Deep-equal membership.
pub fn includes(a: &Value, x: &Value) -> bool {
    as_list(a).iter().any(|y| deep_equal(y, x))
}
pub fn sum(a: &Value, path: &Value) -> f64 {
    let p = str_u(path);
    as_list(a).iter().map(|x| to_num(&if p.is_empty() { x.clone() } else { get_path(x, &ustr(p.clone())) })).fold(0.0, |s, x| s + x)
}
pub fn sort_by(a: &Value, path: &Value, desc: &Value) -> Value {
    let dir = if truthy(desc) { -1 } else { 1 };
    let p = str_u(path);
    let key = |x: &Value| if p.is_empty() { x.clone() } else { get_path(x, &ustr(p.clone())) };
    // a stable merge sort, like Array.prototype.sort (whatever the comparison says)
    let c = |x: &Value, y: &Value| {
        let (u, w) = (key(x), key(y));
        if lt(&u, &w) { -dir } else if lt(&w, &u) { dir } else { 0 }
    };
    list(merge_sort(&as_list(a), &c))
}
fn merge_sort(l: &[Value], c: &dyn Fn(&Value, &Value) -> i32) -> Vec<Value> {
    if l.len() < 2 {
        return l.to_vec();
    }
    let (a, x) = (merge_sort(&l[..l.len() / 2], c), merge_sort(&l[l.len() / 2..], c));
    let mut out = Vec::with_capacity(l.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < x.len() {
        if c(&x[j], &a[i]) < 0 {
            out.push(x[j].clone());
            j += 1;
        } else {
            out.push(a[i].clone());
            i += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&x[j..]);
    out
}
/// The first item, or null.
pub fn first(a: &Value) -> Value {
    as_list(a).first().cloned().unwrap_or(NULL)
}
/// The last item, or null.
pub fn last(a: &Value) -> Value {
    as_list(a).last().cloned().unwrap_or(NULL)
}
/// Groups items by the text of a path: { value: [items] }.
pub fn group_by(a: &Value, path: &Value) -> Value {
    let p = str_u(path);
    let mut groups: Vec<(Vec<u16>, Vec<Value>)> = Vec::new();
    for x in as_list(a).iter() {
        let k = str_u(&to_string_value(&if p.is_empty() { x.clone() } else { get_path(x, &ustr(p.clone())) }));
        match groups.iter_mut().find(|(g, _)| *g == k) {
            Some(g) => g.1.push(x.clone()),
            None => groups.push((k, vec![x.clone()])),
        }
    }
    obj_units(groups.into_iter().map(|(k, l)| (Str::from(k), list(l))).collect())
}
/// The mean of numbers or of a path; 0 for an empty list.
pub fn average(a: &Value, path: &Value) -> f64 {
    let c = as_list(a).len();
    if c == 0 { 0.0 } else { sum(a, path) / c as f64 }
}

// ---------- validation: every check returns { valid, message } ----------

fn valid() -> Value {
    obj(vec![("valid", b(true)), ("message", s(""))])
}
fn invalid(message: Vec<u16>) -> Value {
    obj(vec![("valid", b(false)), ("message", ustr(message))])
}
fn msg(parts: &[&[u16]]) -> Vec<u16> {
    parts.concat()
}
pub fn check_required(v: &Value, field: &Value) -> Value {
    if is_empty(v) { invalid(msg(&[&str_u(field), &units(" is required")])) } else { valid() }
}
pub fn check_email(v: &Value, field: &Value) -> Value {
    let ok = matches!(v, Value::Str(t) if Regex::new(&units("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"), "").unwrap().search(t).is_some());
    if ok { valid() } else { invalid(msg(&[&str_u(field), &units(" must be a valid email")])) }
}
fn value_type(v: &Value) -> &'static str {
    match v {
        Value::Null => "null",
        Value::List(_) => "array",
        Value::Num(x) => if x.is_finite() && x.floor() == *x { "integer" } else { "number" },
        Value::Str(_) => "string",
        Value::Bool(_) => "boolean",
        Value::Obj(_) => "object",
    }
}
pub fn check_type(v: &Value, kind: &Value, field: &Value) -> Value {
    let vt = value_type(v);
    let t = text(&str_u(kind));
    if vt == t || (t == "number" && vt == "integer") { valid() } else { invalid(msg(&[&str_u(field), &units(" must be "), &units(&t)])) }
}
/// The first problem of a value against a shape, or None.
fn check_value(v: &Value, shape: &Value, path: &[u16]) -> Option<Vec<u16>> {
    if !matches!(shape, Value::Obj(_)) {
        return None;
    }
    let kind = get(shape, "type");
    if eq(&kind, &s("any")) {
        return None;
    }
    if v.is_null() {
        return if truthy(&get(shape, "nullable")) || eq(&kind, &s("null")) { None } else { Some(msg(&[path, &units(" is null")])) };
    }
    let t = value_type(v);
    if eq(&kind, &s("number")) && (t == "integer" || t == "number") {
        return None;
    }
    if !eq(&kind, &s(t)) {
        return Some(msg(&[path, &units(": expected "), &str_u(&kind), &units(", got "), &units(t)]));
    }
    if let Value::List(en) = get(shape, "enum") {
        if !en.is_empty() && !includes(&Value::List(en.clone()), v) {
            let names = join_units(en.iter().map(js_string).collect(), &units(", "));
            return Some(msg(&[path, &units(": "), &json_units(v), &units(" is not one of "), &names]));
        }
    }
    if let (Value::Obj(props), Value::Obj(o)) = (get(shape, "properties"), v) {
        for k in key_list(&props) {
            let at = msg(&[path, &units("."), &k]);
            let ps = props.get(&k).unwrap();
            match o.get(&k) {
                None => {
                    if truthy(&get(ps, "required")) {
                        return Some(msg(&[&at, &units(" is missing")]));
                    }
                }
                Some(x) => {
                    if let Some(p) = check_value(x, ps, &at) {
                        return Some(p);
                    }
                }
            }
        }
    }
    if let Value::List(l) = v {
        let items = get(shape, "items");
        for (i, x) in l.iter().enumerate() {
            if let Some(p) = check_value(x, &items, &msg(&[path, &units(&format!("[{}]", i))])) {
                return Some(p);
            }
        }
    }
    None
}
pub fn check_shape(v: &Value, shape: &Value, field: &Value) -> Value {
    match check_value(v, shape, &str_u(field)) {
        Some(p) => invalid(p),
        None => valid(),
    }
}
pub fn check_range(v: &Value, lo: &Value, hi: &Value, field: &Value) -> Value {
    let x = match v {
        Value::Num(x) => *x,
        _ => return invalid(msg(&[&str_u(field), &units(" must be a number")])),
    };
    let blank = |b: &Value| b.is_null() || eq(b, &s(""));
    if !blank(lo) && x < to_num(lo) {
        return invalid(msg(&[&str_u(field), &units(" must be ≥ "), &js_string(lo)]));
    }
    if !blank(hi) && x > to_num(hi) {
        return invalid(msg(&[&str_u(field), &units(" must be ≤ "), &js_string(hi)]));
    }
    valid()
}
pub fn check_regex(v: &Value, pattern: &Value, field: &Value) -> Value {
    match Regex::new(&str_u(pattern), "") {
        Err(_) => invalid(units("invalid pattern")),
        Ok(re) => if re.search(&str_u(v)).is_some() { valid() } else { invalid(msg(&[&str_u(field), &units(" has an invalid format")])) },
    }
}
pub fn check_password(v: &Value, policy: &Value, field: &Value) -> Value {
    let p = str_u(v);
    let min = to_num(&get(policy, "minLength"));
    if (p.len() as f64) < min {
        return invalid(msg(&[&str_u(field), &units(&format!(" must be at least {} characters", num_text(min)))]));
    }
    if truthy(&get(policy, "requireDigit")) && !p.iter().any(|c| (0x30..=0x39).contains(c)) {
        return invalid(msg(&[&str_u(field), &units(" must contain a digit")]));
    }
    if truthy(&get(policy, "requireUpper")) && !p.iter().any(|c| (0x41..=0x5a).contains(c)) {
        return invalid(msg(&[&str_u(field), &units(" must contain an uppercase letter")]));
    }
    valid()
}

// ---------- conversion ----------

/// Objects become JSON.
pub fn to_string_value(v: &Value) -> Value {
    if container(v) { ustr(json_units(v)) } else { str(v) }
}
/// Not a number is 0.
pub fn to_number(v: &Value) -> f64 {
    let x = js_number(v);
    if x.is_nan() { 0.0 } else { x }
}
pub fn is_numeric(v: &Value) -> bool {
    !js_number(v).is_nan()
}
pub fn to_boolean(v: &Value) -> bool {
    truthy(v)
}
/// string, integer, number, boolean, object, array or null.
pub fn type_of(v: &Value) -> Value {
    s(value_type(v))
}

// ---------- math ----------

/// Math.min and Math.max: NaN wins, -0 is below 0.
fn js_min(a: f64, x: f64) -> f64 {
    if a.is_nan() || x.is_nan() {
        return f64::NAN;
    }
    if a == x {
        return if a.is_sign_negative() { a } else { x };
    }
    if a < x { a } else { x }
}
fn js_max(a: f64, x: f64) -> f64 {
    if a.is_nan() || x.is_nan() {
        return f64::NAN;
    }
    if a == x {
        return if a.is_sign_negative() { x } else { a };
    }
    if a > x { a } else { x }
}
/// 0-15 decimals, halves up.
pub fn round(v: &Value, decimals: &Value) -> f64 {
    let x = to_num(v);
    let d = trunc(to_num(decimals));
    let f = 10f64.powi(if d.is_finite() { d.clamp(0.0, 15.0) as i32 } else { 0 });
    let y = x * f + 0.5;
    if y.is_finite() { y.floor() / f } else { x }
}
pub fn floor(v: &Value) -> f64 {
    to_num(v).floor()
}
pub fn ceil(v: &Value) -> f64 {
    to_num(v).ceil()
}
pub fn abs(v: &Value) -> f64 {
    to_num(v).abs()
}
pub fn min(a: &Value, x: &Value) -> f64 {
    js_min(to_num(a), to_num(x))
}
pub fn max(a: &Value, x: &Value) -> f64 {
    js_max(to_num(a), to_num(x))
}
/// Keeps the value between lo and hi.
pub fn clamp(v: &Value, lo: &Value, hi: &Value) -> f64 {
    js_min(js_max(to_num(v), to_num(lo)), to_num(hi))
}
/// JavaScript's ** (1 ** Infinity is NaN).
pub fn power(a: &Value, x: &Value) -> f64 {
    let (p, q) = (to_num(a), to_num(x));
    if q.is_nan() || (p.abs() == 1.0 && q.is_infinite()) {
        return f64::NAN;
    }
    p.powf(q)
}
pub fn sqrt(v: &Value) -> f64 {
    to_num(v).sqrt()
}

// ---------- text and encoding ----------

/// A slice position: negative counts from the end, clamped to 0..n.
fn rel_index(v: &Value, len: usize) -> usize {
    let r = trunc(to_num(v));
    if r.is_nan() {
        return 0;
    }
    if r < 0.0 { (len as f64 + r).max(0.0) as usize } else { r.min(len as f64) as usize }
}
/// Like String.prototype.slice; a null end means the end of the text.
pub fn substring(t: &Value, start: &Value, end: &Value) -> Value {
    let u = str_u(t);
    let i = rel_index(start, u.len());
    let j = if end.is_null() { u.len() } else { rel_index(end, u.len()) };
    ustr(if j <= i { Vec::new() } else { u[i..j].to_vec() })
}
pub fn index_of(t: &Value, x: &Value) -> f64 {
    unit_index(&str_u(t), &str_u(x)).map_or(-1.0, |i| i as f64)
}
fn pad(t: &Value, length: &Value, fill: &Value, start: bool) -> Res<Value> {
    let u = str_u(t);
    let want = trunc(to_num(length));
    if want > 100_000.0 {
        return Err(FddError::new("INVALID_LENGTH", "Length must be at most 100000"));
    }
    let f = if fill.is_null() { units(" ") } else { str_u(fill) };
    if want.is_nan() || want <= u.len() as f64 || f.is_empty() {
        return Ok(ustr(u));
    }
    let need = want as usize - u.len();
    let p: Vec<u16> = f.iter().cycle().take(need).copied().collect();
    Ok(ustr(if start { [p, u].concat() } else { [u, p].concat() }))
}
pub fn pad_start(t: &Value, length: &Value, fill: &Value) -> Res<Value> {
    pad(t, length, fill, true)
}
pub fn pad_end(t: &Value, length: &Value, fill: &Value) -> Res<Value> {
    pad(t, length, fill, false)
}
const B64: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
fn b64(bytes: &[u8]) -> String {
    let mut out = String::new();
    for c in bytes.chunks(3) {
        let x = (c[0] as u32) << 16 | (*c.get(1).unwrap_or(&0) as u32) << 8 | *c.get(2).unwrap_or(&0) as u32;
        for k in 0..4 {
            out.push(if k <= c.len() { B64[(x >> (18 - 6 * k) & 63) as usize] as char } else { '=' });
        }
    }
    out
}
/// UTF-8 text as Base64.
pub fn base64_encode(t: &Value) -> Value {
    s(&b64(&utf8(&str_u(t))))
}
/// Base64 as UTF-8 text; fails with INVALID_BASE64.
pub fn base64_decode(t: &Value) -> Res<Value> {
    let mut u: Vec<u16> = str_u(t).into_iter().filter(|c| !matches!(c, 0x09 | 0x0a | 0x0c | 0x0d | 0x20)).collect();
    if u.len() % 4 == 0 {
        for _ in 0..2 {
            if u.last() == Some(&0x3d) {
                u.pop();
            }
        }
    }
    let bad = || FddError::new("INVALID_BASE64", "Not valid Base64");
    if u.len() % 4 == 1 {
        return Err(bad());
    }
    let mut bits = 0u32;
    let mut count = 0;
    let mut bytes = Vec::new();
    for c in u {
        let v = B64.iter().position(|x| *x as u16 == c).ok_or_else(bad)? as u32;
        bits = bits << 6 | v;
        count += 6;
        if count >= 8 {
            count -= 8;
            bytes.push((bits >> count & 0xff) as u8);
        }
    }
    // invalid UTF-8 becomes U+FFFD, like TextDecoder
    Ok(s(&String::from_utf8_lossy(&bytes)))
}
/// Fixed decimals (halves up) and a thousands separator; fails with INVALID_NUMBER.
pub fn format_number(value: &Value, decimals: &Value, thousands: &Value, point: &Value) -> Res<Value> {
    let d0 = trunc(to_num(decimals));
    let d = if d0.is_finite() { d0.clamp(0.0, 15.0) as usize } else { 0 };
    let r = round(value, &n(d as f64));
    if !r.is_finite() || r.abs() >= 1e21 {
        return Err(FddError::new("INVALID_NUMBER", "Not a number that can be formatted"));
    }
    let fixed = format!("{:.*}", d, r.abs());
    let (whole, frac) = fixed.split_once('.').unwrap_or((&fixed, ""));
    let neg = r < 0.0 && fixed.chars().any(|c| ('1'..='9').contains(&c));
    let sep = str_u(thousands);
    let mut out: Vec<u16> = if neg { units("-") } else { Vec::new() };
    let w = units(whole);
    for (i, c) in w.iter().enumerate() {
        if i > 0 && (w.len() - i) % 3 == 0 {
            out.extend_from_slice(&sep);
        }
        out.push(*c);
    }
    if !frac.is_empty() {
        out.extend(str_u(point));
        out.extend(units(frac));
    }
    Ok(ustr(out))
}
fn digest_algorithm(a: &Value) -> Res<fn(&[u8]) -> Vec<u8>> {
    let k: String = text(js_trim(&str_u(a))).to_lowercase().replace('-', "");
    match k.as_str() {
        "sha256" => Ok(sha256),
        "sha1" => Ok(sha1),
        "md5" => Ok(md5),
        _ => Err(FddError {
            code: units("INVALID_ALGORITHM").into(),
            message: msg(&[&units("Unknown hash algorithm \""), &str_u(a), &units("\" (use sha256, sha1 or md5)")]).into(),
            stop: false,
        }),
    }
}
fn encode_digest(raw: &[u8], encoding: &Value) -> Res<Value> {
    match text(js_trim(&str_u(encoding))).to_lowercase().as_str() {
        "hex" => Ok(s(&raw.iter().map(|x| format!("{:02x}", x)).collect::<String>())),
        "base64" => Ok(s(&b64(raw))),
        _ => Err(FddError {
            code: units("INVALID_ENCODING").into(),
            message: msg(&[&units("Unknown encoding \""), &str_u(encoding), &units("\" (use hex or base64)")]).into(),
            stop: false,
        }),
    }
}
/// SHA-256, SHA-1 or MD5 of UTF-8 text, as hex or Base64.
pub fn hash_text(t: &Value, algorithm: &Value, encoding: &Value) -> Res<Value> {
    let d = digest_algorithm(algorithm)?;
    encode_digest(&d(&utf8(&str_u(t))), encoding)
}
/// The HMAC of UTF-8 text with a UTF-8 key, as hex or Base64.
pub fn hmac(t: &Value, key: &Value, algorithm: &Value, encoding: &Value) -> Res<Value> {
    let d = digest_algorithm(algorithm)?;
    let mut k = utf8(&str_u(key));
    if k.len() > 64 {
        k = d(&k);
    }
    k.resize(64, 0);
    let inner = d(&[k.iter().map(|x| x ^ 0x36).collect::<Vec<u8>>(), utf8(&str_u(t))].concat());
    encode_digest(&d(&[k.iter().map(|x| x ^ 0x5c).collect::<Vec<u8>>(), inner].concat()), encoding)
}
/// encodeURIComponent.
pub fn url_encode(t: &Value) -> Value {
    let mut out = String::new();
    for x in utf8(&str_u(t)) {
        if x.is_ascii_alphanumeric() || b"-_.!~*'()".contains(&x) {
            out.push(x as char);
        } else {
            out.push_str(&format!("%{:02X}", x));
        }
    }
    s(&out)
}
/// decodeURIComponent; fails with INVALID_URL_ENCODING.
pub fn url_decode(t: &Value) -> Res<Value> {
    let u = str_u(t);
    let bad = || FddError::new("INVALID_URL_ENCODING", "Not valid URL encoding");
    let hex = |c: u16| (c as u8 as char).to_digit(16).filter(|_| c < 0x80);
    let mut out = Vec::new();
    let mut i = 0;
    while i < u.len() {
        if u[i] != 0x25 {
            out.push(u[i]);
            i += 1;
            continue;
        }
        let mut bytes = Vec::new();
        while i < u.len() && u[i] == 0x25 {
            match (u.get(i + 1).and_then(|c| hex(*c)), u.get(i + 2).and_then(|c| hex(*c))) {
                (Some(h), Some(l)) => bytes.push((h * 16 + l) as u8),
                _ => return Err(bad()),
            }
            i += 3;
        }
        out.extend(units(std::str::from_utf8(&bytes).map_err(|_| bad())?));
    }
    Ok(ustr(out))
}

// ---------- records and lists ----------

fn index_key(k: &[u16]) -> bool {
    !k.is_empty() && k.iter().all(|c| (0x30..=0x39).contains(c)) && (k.len() == 1 || k[0] != 0x30) && text(k).parse::<f64>().is_ok_and(|x| x < 4_294_967_295.0)
}
/// Field names in JavaScript's order: integer-like keys ascending, then the rest as inserted.
fn key_list(o: &Object) -> Vec<Vec<u16>> {
    let mut ints: Vec<Vec<u16>> = o.entries.iter().map(|(k, _)| k.to_vec()).filter(|k| index_key(k)).collect();
    ints.sort_by(|a, x| text(a).parse::<f64>().unwrap().partial_cmp(&text(x).parse::<f64>().unwrap()).unwrap());
    ints.extend(o.entries.iter().map(|(k, _)| k.to_vec()).filter(|k| !index_key(k)));
    ints
}
pub fn keys(o: &Value) -> Value {
    match o {
        Value::Obj(m) => list(key_list(m).into_iter().map(ustr).collect()),
        _ => list(vec![]),
    }
}
pub fn values(o: &Value) -> Value {
    match o {
        Value::Obj(m) => list(key_list(m).iter().map(|k| m.get(k).unwrap().clone()).collect()),
        _ => list(vec![]),
    }
}
pub fn entries(o: &Value) -> Value {
    match o {
        Value::Obj(m) => list(key_list(m).into_iter().map(|k| obj(vec![("key", ustr(k.clone())), ("value", m.get(&k).unwrap().clone())])).collect()),
        _ => list(vec![]),
    }
}
/// Like Array.prototype.slice; a null end means the end of the list.
pub fn slice(a: &Value, start: &Value, end: &Value) -> Value {
    let l = as_list(a);
    let i = rel_index(start, l.len());
    let j = if end.is_null() { l.len() } else { rel_index(end, l.len()) };
    list(if j <= i { Vec::new() } else { l[i..j].to_vec() })
}
pub fn reverse(a: &Value) -> Value {
    list(as_list(a).iter().rev().cloned().collect())
}
/// Removes deep-equal duplicates, the first kept.
pub fn unique(a: &Value) -> Value {
    let mut out: Vec<Value> = Vec::new();
    for x in as_list(a).iter() {
        if !out.iter().any(|y| deep_equal(y, x)) {
            out.push(x.clone());
        }
    }
    list(out)
}
/// The deep-equal position, or -1.
pub fn item_index(a: &Value, x: &Value) -> f64 {
    as_list(a).iter().position(|y| deep_equal(y, x)).map_or(-1.0, |i| i as f64)
}
/// Flattens one level.
pub fn flatten(a: &Value) -> Value {
    list(as_list(a).iter().flat_map(|x| match x {
        Value::List(l) => l.to_vec(),
        _ => vec![x.clone()],
    }).collect())
}

// ---------- dates: ISO 8601 text in UTC; numbers are epoch milliseconds ----------

const MIN_MS: i64 = -62_167_219_200_000;
const MAX_MS: i64 = 253_402_300_799_999;
const DAY_MS: i64 = 86_400_000;
const MONTHS: [&str; 12] = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const DAYS: [&str; 7] = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const DATE_TOKENS: [&str; 20] = ["yyyy", "yy", "MMMM", "MMM", "MM", "M", "dd", "d", "EEEE", "EEE", "HH", "H", "hh", "h", "mm", "m", "ss", "s", "SSS", "a"];

fn bad_date() -> FddError {
    FddError::new("INVALID_DATE", "Not a valid date")
}
fn out_of_range() -> FddError {
    FddError::new("INVALID_DATE", "The date is out of range")
}
/// Days since 1970-01-01 (proleptic Gregorian).
fn days_from_civil(y: i64, m: i64, d: i64) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = y.div_euclid(400);
    let yoe = y - era * 400;
    let doy = (153 * (if m > 2 { m - 3 } else { m + 9 }) + 2) / 5 + d - 1;
    era * 146_097 + yoe * 365 + yoe / 4 - yoe / 100 + doy - 719_468
}
fn civil_from_days(z: i64) -> (i64, i64, i64) {
    let z = z + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    (yoe + era * 400 + if m <= 2 { 1 } else { 0 }, m, doy - (153 * mp + 2) / 5 + 1)
}
fn days_in(y: i64, m: i64) -> i64 {
    match m {
        2 => if y % 4 == 0 && (y % 100 != 0 || y % 400 == 0) { 29 } else { 28 },
        4 | 6 | 9 | 11 => 30,
        _ => 31,
    }
}
thread_local! {
    static DATE_RE: Regex = Regex::new(&units("^([0-9]{4})-([0-9]{2})-([0-9]{2})(?:[Tt ]([0-9]{2}):([0-9]{2})(?::([0-9]{2})(?:\\.([0-9]+))?)?)?(?:([Zz])|([+-])([0-9]{2}):?([0-9]{2}))?$"), "").unwrap();
}
/// The epoch milliseconds of a date (years 0-9999), or None.
fn date_ms(v: &Value) -> Option<i64> {
    if let Value::Num(x) = v {
        if !x.is_finite() || trunc(*x) < MIN_MS as f64 || trunc(*x) > MAX_MS as f64 {
            return None;
        }
        return Some(trunc(*x) as i64);
    }
    let t = match v {
        Value::Str(t) => js_trim(t).to_vec(),
        _ => return None,
    };
    let caps = DATE_RE.with(|re| re.search(&t))?;
    let part = |k: usize| caps[k].map(|(a, z)| text(&t[a..z]));
    let g = |k: usize| part(k).map_or(0, |x| x.parse::<i64>().unwrap());
    let (y, mo, d, h, mi, sec) = (g(1), g(2), g(3), g(4), g(5), g(6));
    if !(1..=12).contains(&mo) || d < 1 || d > days_in(y, mo) || h > 23 || mi > 59 || sec > 59 {
        return None;
    }
    let tz = part(9);
    if tz.is_some() && (g(10) > 23 || g(11) > 59) {
        return None;
    }
    let mut off = if tz.is_some() { g(10) * 60 + g(11) } else { 0 };
    if tz.as_deref() == Some("-") {
        off = -off;
    }
    let frac = format!("{}000", part(7).unwrap_or_default())[..3].parse::<i64>().unwrap();
    let ms = ((days_from_civil(y, mo, d) * 86_400 + h * 3600 + mi * 60 + sec) * 1000 + frac) - off * 60_000;
    if (MIN_MS..=MAX_MS).contains(&ms) { Some(ms) } else { None }
}
fn need_date(v: &Value) -> Res<i64> {
    date_ms(v).ok_or_else(bad_date)
}
/// [year, month, day, hour, minute, second, millisecond, weekday (0 = Sunday), time of day]
fn date_fields(ms: i64) -> [i64; 9] {
    let days = ms.div_euclid(DAY_MS);
    let t = ms - days * DAY_MS;
    let (y, m, d) = civil_from_days(days);
    [y, m, d, t / 3_600_000, (t / 60_000) % 60, (t / 1000) % 60, t % 1000, (days + 4).rem_euclid(7), t]
}
fn iso_date(ms: i64) -> Res<Value> {
    if !(MIN_MS..=MAX_MS).contains(&ms) {
        return Err(out_of_range());
    }
    let p = date_fields(ms);
    Ok(s(&format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:03}Z", p[0], p[1], p[2], p[3], p[4], p[5], p[6])))
}
/// The milliseconds of a unit; months are -1 and years -12.
fn time_unit(u: &Value) -> Res<i64> {
    Ok(match text(js_trim(&str_u(u))).to_lowercase().as_str() {
        "millisecond" | "milliseconds" | "ms" => 1,
        "second" | "seconds" => 1000,
        "minute" | "minutes" => 60_000,
        "hour" | "hours" => 3_600_000,
        "day" | "days" => DAY_MS,
        "week" | "weeks" => 7 * DAY_MS,
        "month" | "months" => -1,
        "year" | "years" => -12,
        _ => {
            return Err(FddError {
                code: units("INVALID_UNIT").into(),
                message: msg(&[&units("Unknown time unit \""), &str_u(u), &units("\"")]).into(),
                stop: false,
            })
        }
    })
}
/// A date as UTC date-time text and epoch milliseconds.
pub fn parse_date(v: &Value) -> Res<Value> {
    Ok(match date_ms(v) {
        None => obj(vec![("date", NULL), ("timestamp", NULL), ("valid", b(false))]),
        Some(ms) => obj(vec![("date", iso_date(ms)?), ("timestamp", n(ms as f64)), ("valid", b(true))]),
    })
}
/// yyyy yy MMMM MMM MM M dd d EEEE EEE HH H hh h mm m ss s SSS a; text in single quotes is kept as is, and two single quotes are one.
pub fn format_date(date: &Value, pattern: &Value) -> Res<Value> {
    let p = date_fields(need_date(date)?);
    let f: Vec<char> = text(&str_u(pattern)).chars().collect();
    let h12 = if p[3] % 12 == 0 { 12 } else { p[3] % 12 };
    let month = MONTHS[(p[1] - 1) as usize];
    let day = DAYS[p[7] as usize];
    let vals = [
        format!("{:04}", p[0]), format!("{:02}", p[0] % 100), month.into(), month[..3].into(), format!("{:02}", p[1]), p[1].to_string(),
        format!("{:02}", p[2]), p[2].to_string(), day.into(), day[..3].into(), format!("{:02}", p[3]), p[3].to_string(), format!("{:02}", h12),
        h12.to_string(), format!("{:02}", p[4]), p[4].to_string(), format!("{:02}", p[5]), p[5].to_string(), format!("{:03}", p[6]),
        (if p[3] < 12 { "AM" } else { "PM" }).into(),
    ];
    let mut out = String::new();
    let mut i = 0;
    while i < f.len() {
        if f[i] == '\'' {
            if f.get(i + 1) == Some(&'\'') {
                out.push('\'');
                i += 2;
                continue;
            }
            i += 1;
            while i < f.len() {
                if f[i] != '\'' {
                    out.push(f[i]);
                } else if f.get(i + 1) == Some(&'\'') {
                    out.push('\'');
                    i += 1;
                } else {
                    break;
                }
                i += 1;
            }
            i += 1;
            continue;
        }
        match DATE_TOKENS.iter().position(|t| f[i..].iter().take(t.len()).collect::<String>() == *t) {
            Some(k) => {
                out.push_str(&vals[k]);
                i += DATE_TOKENS[k].len();
            }
            None => {
                out.push(f[i]);
                i += 1;
            }
        }
    }
    Ok(s(&out))
}
/// Months and years keep the day, clamped to the end of the month.
pub fn add_time(date: &Value, amount: &Value, unit: &Value) -> Res<Value> {
    let ms = need_date(date)?;
    let u = time_unit(unit)?;
    let x = to_num(amount);
    if !x.is_finite() {
        return Err(out_of_range());
    }
    if u > 0 {
        let at = ms as f64 + (x * u as f64 + 0.5).floor();
        if !(at >= MIN_MS as f64 && at <= MAX_MS as f64) {
            return Err(out_of_range());
        }
        return iso_date(at as i64);
    }
    if trunc(x).abs() > 1e6 {
        return Err(out_of_range());
    }
    let p = date_fields(ms);
    let total = p[0] * 12 + p[1] - 1 + trunc(x) as i64 * -u;
    let y = total.div_euclid(12);
    let m = total - y * 12 + 1;
    iso_date(days_from_civil(y, m, p[2].min(days_in(y, m))) * DAY_MS + p[8])
}
/// Whole units from From to To, toward zero.
pub fn time_between(from: &Value, to: &Value, unit: &Value) -> Res<f64> {
    let (a, z) = (need_date(from)?, need_date(to)?);
    let u = time_unit(unit)?;
    if u > 0 {
        return Ok(trunc((z - a) as f64 / u as f64) + 0.0);
    }
    let (p, q) = (date_fields(a), date_fields(z));
    let mut months = (q[0] - p[0]) * 12 + q[1] - p[1];
    if months > 0 && (q[2] < p[2] || (q[2] == p[2] && q[8] < p[8])) {
        months -= 1;
    } else if months < 0 && (q[2] > p[2] || (q[2] == p[2] && q[8] > p[8])) {
        months += 1;
    }
    Ok(trunc(months as f64 / -u as f64) + 0.0)
}
/// year ... millisecond in UTC, weekday 1 = Monday ... 7 = Sunday.
pub fn date_parts(date: &Value) -> Res<Value> {
    let p = date_fields(need_date(date)?);
    let names = ["year", "month", "day", "hour", "minute", "second", "millisecond"];
    let mut kv: Vec<(&str, Value)> = names.iter().enumerate().map(|(i, k)| (*k, n(p[i] as f64))).collect();
    kv.push(("weekday", n(if p[7] == 0 { 7.0 } else { p[7] as f64 })));
    Ok(obj(kv))
}
/// A UTC date-time from its parts; fails with INVALID_DATE.
pub fn make_date(year: &Value, month: &Value, day: &Value, hour: &Value, minute: &Value, second: &Value) -> Res<Value> {
    let v: Vec<f64> = [year, month, day, hour, minute, second].iter().map(|x| to_num(x)).collect();
    if v.iter().any(|x| !x.is_finite() || x.floor() != *x || x.abs() > 1e15) {
        return Err(bad_date());
    }
    let [y, m, d, h, mi, sec] = [v[0] as i64, v[1] as i64, v[2] as i64, v[3] as i64, v[4] as i64, v[5] as i64];
    if !(0..=9999).contains(&y) || !(1..=12).contains(&m) || d < 1 || d > days_in(y, m) || !(0..=23).contains(&h) || !(0..=59).contains(&mi) || !(0..=59).contains(&sec) {
        return Err(bad_date());
    }
    iso_date((days_from_civil(y, m, d) * 86_400 + h * 3600 + mi * 60 + sec) * 1000)
}
/// The first (or last) millisecond of the hour, day, week from Monday, month or year.
fn period_edge(date: &Value, unit: &Value, end: bool) -> Res<Value> {
    let ms = need_date(date)?;
    let p = date_fields(ms);
    let day = ms - p[8];
    let (from, length) = match text(js_trim(&str_u(unit))).to_lowercase().as_str() {
        "hour" | "hours" => (ms - p[8] % 3_600_000, 3_600_000),
        "day" | "days" => (day, DAY_MS),
        "week" | "weeks" => (day - ((p[7] + 6) % 7) * DAY_MS, 7 * DAY_MS),
        "month" | "months" => (days_from_civil(p[0], p[1], 1) * DAY_MS, days_in(p[0], p[1]) * DAY_MS),
        "year" | "years" => (days_from_civil(p[0], 1, 1) * DAY_MS, (days_from_civil(p[0] + 1, 1, 1) - days_from_civil(p[0], 1, 1)) * DAY_MS),
        _ => {
            return Err(FddError {
                code: units("INVALID_UNIT").into(),
                message: msg(&[&units("Unknown period \""), &str_u(unit), &units("\" (use hour, day, week, month or year)")]).into(),
                stop: false,
            })
        }
    };
    iso_date(if end { from + length - 1 } else { from })
}
/// The first moment of the period the date is in (UTC).
pub fn start_of(date: &Value, unit: &Value) -> Res<Value> {
    period_edge(date, unit, false)
}
/// The last moment (...:59.999) of the period the date is in (UTC).
pub fn end_of(date: &Value, unit: &Value) -> Res<Value> {
    period_edge(date, unit, true)
}

// ---------- runtime ----------

/// The current date-time (ISO, like JavaScript's toISOString).
pub fn now() -> Value {
    let ms = SystemTime::now().duration_since(UNIX_EPOCH).map_or(0, |d| d.as_millis() as i64);
    iso_date(ms).unwrap_or(NULL)
}
thread_local! {
    static SEED: Cell<u64> = Cell::new(RandomState::new().build_hasher().finish() | 1);
}
/// 64 random bits (xorshift, seeded by the standard library's random hash keys)
fn random_bits() -> u64 {
    SEED.with(|c| {
        let mut x = c.get();
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        c.set(x);
        x
    })
}
pub fn uuid() -> Value {
    let mut bs: Vec<u8> = (0..2).flat_map(|_| random_bits().to_le_bytes()).collect();
    bs[6] = (bs[6] & 0x0f) | 0x40;
    bs[8] = (bs[8] & 0x3f) | 0x80;
    let h: String = bs.iter().map(|x| format!("{:02x}", x)).collect();
    s(&format!("{}-{}-{}-{}-{}", &h[..8], &h[8..12], &h[12..16], &h[16..20], &h[20..]))
}
/// An integer between min and max.
pub fn random(min: &Value, max: &Value) -> f64 {
    let (a, z) = (to_num(min), to_num(max));
    let r = (random_bits() >> 11) as f64 / (1u64 << 53) as f64;
    (a + r * (z - a + 1.0)).floor()
}
/// A Parallel step: each branch on a thread of its own. When all are done, the first failing branch's error (in branch
/// order) if one failed.
pub fn parallel<'a>(branches: Vec<Box<dyn FnOnce() -> Res<()> + Send + 'a>>) -> Res<()> {
    let results: Vec<Res<()>> = std::thread::scope(|sc| {
        let running: Vec<_> = branches.into_iter().map(|f| sc.spawn(f)).collect();
        running.into_iter().map(|h| h.join().unwrap_or_else(|p| std::panic::resume_unwind(p))).collect()
    });
    results.into_iter().collect()
}
pub fn log(message: &Value) -> Value {
    match message {
        Value::Str(t) => eprintln!("{}", text(t)),
        _ => eprintln!("{}", message.to_json()),
    }
    NULL
}
pub fn sleep(ms: &Value) -> Value {
    std::thread::sleep(std::time::Duration::from_millis(to_num(ms).max(0.0) as u64));
    NULL
}

// ---------- hashing ----------

fn sha256(data: &[u8]) -> Vec<u8> {
    const K: [u32; 64] = [
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
        0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
        0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
        0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
        0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
        0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
    ];
    let mut h: [u32; 8] = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
    for c in padded(data, true).chunks(64) {
        let mut w = [0u32; 64];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([c[4 * i], c[4 * i + 1], c[4 * i + 2], c[4 * i + 3]]);
        }
        for i in 16..64 {
            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16].wrapping_add(s0).wrapping_add(w[i - 7]).wrapping_add(s1);
        }
        let mut v = h;
        for i in 0..64 {
            let s1 = v[4].rotate_right(6) ^ v[4].rotate_right(11) ^ v[4].rotate_right(25);
            let ch = (v[4] & v[5]) ^ (!v[4] & v[6]);
            let t1 = v[7].wrapping_add(s1).wrapping_add(ch).wrapping_add(K[i]).wrapping_add(w[i]);
            let s0 = v[0].rotate_right(2) ^ v[0].rotate_right(13) ^ v[0].rotate_right(22);
            let mj = (v[0] & v[1]) ^ (v[0] & v[2]) ^ (v[1] & v[2]);
            let t2 = s0.wrapping_add(mj);
            v = [t1.wrapping_add(t2), v[0], v[1], v[2], v[3].wrapping_add(t1), v[4], v[5], v[6]];
        }
        for i in 0..8 {
            h[i] = h[i].wrapping_add(v[i]);
        }
    }
    h.iter().flat_map(|x| x.to_be_bytes()).collect()
}
fn sha1(data: &[u8]) -> Vec<u8> {
    let mut h: [u32; 5] = [0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476, 0xc3d2e1f0];
    for c in padded(data, true).chunks(64) {
        let mut w = [0u32; 80];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([c[4 * i], c[4 * i + 1], c[4 * i + 2], c[4 * i + 3]]);
        }
        for i in 16..80 {
            w[i] = (w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16]).rotate_left(1);
        }
        let mut v = h;
        for (i, x) in w.iter().enumerate() {
            let (f, k) = match i {
                0..=19 => ((v[1] & v[2]) | (!v[1] & v[3]), 0x5a827999),
                20..=39 => (v[1] ^ v[2] ^ v[3], 0x6ed9eba1),
                40..=59 => ((v[1] & v[2]) | (v[1] & v[3]) | (v[2] & v[3]), 0x8f1bbcdc),
                _ => (v[1] ^ v[2] ^ v[3], 0xca62c1d6),
            };
            let t = v[0].rotate_left(5).wrapping_add(f).wrapping_add(v[4]).wrapping_add(k).wrapping_add(*x);
            v = [t, v[0], v[1].rotate_left(30), v[2], v[3]];
        }
        for i in 0..5 {
            h[i] = h[i].wrapping_add(v[i]);
        }
    }
    h.iter().flat_map(|x| x.to_be_bytes()).collect()
}
fn md5(data: &[u8]) -> Vec<u8> {
    const S: [u32; 64] = [
        7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 4, 11, 16, 23, 4, 11, 16, 23,
        4, 11, 16, 23, 4, 11, 16, 23, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
    ];
    let k: Vec<u32> = (0..64).map(|i| ((i as f64 + 1.0).sin().abs() * 4_294_967_296.0) as u32).collect();
    let mut h: [u32; 4] = [0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476];
    for c in padded(data, false).chunks(64) {
        let m: Vec<u32> = (0..16).map(|i| u32::from_le_bytes([c[4 * i], c[4 * i + 1], c[4 * i + 2], c[4 * i + 3]])).collect();
        let [mut a, mut x, mut y, mut z] = h;
        for i in 0..64 {
            let (f, g) = match i {
                0..=15 => ((x & y) | (!x & z), i),
                16..=31 => ((z & x) | (!z & y), (5 * i + 1) % 16),
                32..=47 => (x ^ y ^ z, (3 * i + 5) % 16),
                _ => (y ^ (x | !z), (7 * i) % 16),
            };
            let f2 = f.wrapping_add(a).wrapping_add(k[i]).wrapping_add(m[g]);
            a = z;
            z = y;
            y = x;
            x = x.wrapping_add(f2.rotate_left(S[i]));
        }
        h = [h[0].wrapping_add(a), h[1].wrapping_add(x), h[2].wrapping_add(y), h[3].wrapping_add(z)];
    }
    h.iter().flat_map(|x| x.to_le_bytes()).collect()
}
/// the message with its padding and bit length (big-endian for SHA, little-endian for MD5)
fn padded(data: &[u8], big: bool) -> Vec<u8> {
    let mut m = data.to_vec();
    m.push(0x80);
    while m.len() % 64 != 56 {
        m.push(0);
    }
    let bits = (data.len() as u64).wrapping_mul(8);
    m.extend(if big { bits.to_be_bytes() } else { bits.to_le_bytes() });
    m
}

// ---------- regular expressions (JavaScript's syntax and backtracking, on UTF-16 units) ----------

#[derive(Debug, Clone)]
enum Node {
    Unit(u16),
    Any,
    Class(Vec<(u16, u16)>, bool),
    Start,
    End,
    Word(bool),
    Group(Box<Node>, Option<usize>),
    Look(Box<Node>, bool, bool),
    Backref(usize),
    Alt(Vec<Node>),
    Seq(Vec<Node>),
    Repeat(Box<Node>, usize, usize, bool),
}

struct Regex {
    node: Node,
    groups: usize,
    icase: bool,
    multiline: bool,
    dot_all: bool,
}

type Caps = Vec<Option<(usize, usize)>>;

const DIGIT: &[(u16, u16)] = &[(0x30, 0x39)];
const WORD: &[(u16, u16)] = &[(0x30, 0x39), (0x41, 0x5a), (0x5f, 0x5f), (0x61, 0x7a)];
const SPACE: &[(u16, u16)] = &[(0x09, 0x0d), (0x20, 0x20), (0xa0, 0xa0), (0x1680, 0x1680), (0x2000, 0x200a), (0x2028, 0x2029), (0x202f, 0x202f), (0x205f, 0x205f), (0x3000, 0x3000), (0xfeff, 0xfeff)];

fn negate(r: &[(u16, u16)]) -> Vec<(u16, u16)> {
    let mut sorted = r.to_vec();
    sorted.sort();
    let mut out = Vec::new();
    let mut at: u32 = 0;
    for (a, z) in sorted {
        if (a as u32) > at {
            out.push((at as u16, a - 1));
        }
        at = at.max(z as u32 + 1);
    }
    if at <= 0xffff {
        out.push((at as u16, 0xffff));
    }
    out
}

struct Parser<'a> {
    p: &'a [u16],
    i: usize,
    groups: usize,
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<u16> {
        self.p.get(self.i).copied()
    }
    fn eat(&mut self, c: u16) -> bool {
        if self.peek() == Some(c) {
            self.i += 1;
            true
        } else {
            false
        }
    }
    fn alt(&mut self) -> Result<Node, ()> {
        let mut options = vec![self.seq()?];
        while self.eat(0x7c) {
            options.push(self.seq()?);
        }
        Ok(if options.len() == 1 { options.pop().unwrap() } else { Node::Alt(options) })
    }
    fn seq(&mut self) -> Result<Node, ()> {
        let mut items = Vec::new();
        while let Some(c) = self.peek() {
            if c == 0x7c || c == 0x29 {
                break;
            }
            let atom = self.atom()?;
            items.push(self.quantified(atom)?);
        }
        Ok(Node::Seq(items))
    }
    /// {n}, {n,} or {n,m} at the parser's position, or None (then { is a plain character)
    fn braces(&mut self) -> Option<(usize, usize)> {
        let save = self.i;
        self.i += 1;
        let num = |s: &mut Self| {
            let a = s.i;
            while s.peek().is_some_and(|c| (0x30..=0x39).contains(&c)) {
                s.i += 1;
            }
            if s.i == a { None } else { text(&s.p[a..s.i]).parse::<usize>().ok().or(Some(usize::MAX)) }
        };
        let lo = num(self);
        let r = lo.and_then(|lo| {
            if self.eat(0x7d) {
                return Some((lo, lo));
            }
            if !self.eat(0x2c) {
                return None;
            }
            if self.eat(0x7d) {
                return Some((lo, usize::MAX));
            }
            let hi = num(self)?;
            if self.eat(0x7d) { Some((lo, hi)) } else { None }
        });
        if r.is_none() {
            self.i = save;
        }
        r
    }
    fn quantified(&mut self, atom: Node) -> Result<Node, ()> {
        let (lo, hi) = match self.peek() {
            Some(0x2a) => { self.i += 1; (0, usize::MAX) }
            Some(0x2b) => { self.i += 1; (1, usize::MAX) }
            Some(0x3f) => { self.i += 1; (0, 1) }
            Some(0x7b) => match self.braces() {
                Some(r) => r,
                None => return Ok(atom),
            },
            _ => return Ok(atom),
        };
        if lo > hi || matches!(atom, Node::Start | Node::End | Node::Word(_)) {
            return Err(());
        }
        let greedy = !self.eat(0x3f);
        Ok(Node::Repeat(Box::new(atom), lo, hi, greedy))
    }
    fn atom(&mut self) -> Result<Node, ()> {
        let c = self.peek().ok_or(())?;
        self.i += 1;
        Ok(match c {
            0x5e => Node::Start,
            0x24 => Node::End,
            0x2e => Node::Any,
            0x2a | 0x2b | 0x3f => return Err(()),
            0x7b => {
                self.i -= 1;
                if self.braces().is_some() {
                    return Err(());
                }
                self.i += 1;
                Node::Unit(c)
            }
            0x28 => {
                let node = if self.eat(0x3f) {
                    if self.eat(0x3a) {
                        Node::Group(Box::new(self.alt()?), None)
                    } else if self.eat(0x3d) {
                        Node::Look(Box::new(self.alt()?), true, false)
                    } else if self.eat(0x21) {
                        Node::Look(Box::new(self.alt()?), false, false)
                    } else if self.eat(0x3c) {
                        if self.eat(0x3d) {
                            Node::Look(Box::new(self.alt()?), true, true)
                        } else if self.eat(0x21) {
                            Node::Look(Box::new(self.alt()?), false, true)
                        } else {
                            // (?<name>...): a numbered group
                            while self.peek().is_some_and(|x| x != 0x3e) {
                                self.i += 1;
                            }
                            if !self.eat(0x3e) {
                                return Err(());
                            }
                            self.groups += 1;
                            let g = self.groups;
                            Node::Group(Box::new(self.alt()?), Some(g))
                        }
                    } else {
                        return Err(());
                    }
                } else {
                    self.groups += 1;
                    let g = self.groups;
                    Node::Group(Box::new(self.alt()?), Some(g))
                };
                if !self.eat(0x29) {
                    return Err(());
                }
                node
            }
            0x29 => return Err(()),
            0x5b => self.class()?,
            0x5c => self.escape(false)?,
            _ => Node::Unit(c),
        })
    }
    /// after a backslash
    fn escape(&mut self, in_class: bool) -> Result<Node, ()> {
        let c = self.peek().ok_or(())?;
        self.i += 1;
        let set = |r: &[(u16, u16)], neg: bool| Node::Class(r.to_vec(), neg);
        Ok(match c {
            0x64 => set(DIGIT, false),
            0x44 => set(DIGIT, true),
            0x77 => set(WORD, false),
            0x57 => set(WORD, true),
            0x73 => set(SPACE, false),
            0x53 => set(SPACE, true),
            0x62 if !in_class => Node::Word(true),
            0x42 if !in_class => Node::Word(false),
            0x62 => Node::Unit(0x08),
            0x6e => Node::Unit(0x0a),
            0x72 => Node::Unit(0x0d),
            0x74 => Node::Unit(0x09),
            0x76 => Node::Unit(0x0b),
            0x66 => Node::Unit(0x0c),
            0x30 if !self.peek().is_some_and(|x| (0x30..=0x39).contains(&x)) => Node::Unit(0),
            0x31..=0x39 if !in_class => {
                let a = self.i - 1;
                while self.peek().is_some_and(|x| (0x30..=0x39).contains(&x)) {
                    self.i += 1;
                }
                Node::Backref(text(&self.p[a..self.i]).parse().map_err(|_| ())?)
            }
            0x78 | 0x75 => {
                let k = if c == 0x78 { 2 } else { 4 };
                let h = self.p.get(self.i..self.i + k).map(text).filter(|h| h.chars().all(|x| x.is_ascii_hexdigit()));
                match h {
                    Some(h) => {
                        self.i += k;
                        Node::Unit(u16::from_str_radix(&h, 16).unwrap())
                    }
                    None => Node::Unit(c),
                }
            }
            0x63 => match self.peek() {
                Some(x) if (x as u8 as char).is_ascii_alphabetic() && x < 0x80 => {
                    self.i += 1;
                    Node::Unit(x % 32)
                }
                _ => {
                    self.i -= 1;
                    Node::Unit(0x5c)
                }
            },
            _ => Node::Unit(c),
        })
    }
    fn class(&mut self) -> Result<Node, ()> {
        let neg = self.eat(0x5e);
        let mut ranges = Vec::new();
        let mut first = true;
        loop {
            let c = self.peek().ok_or(())?;
            if c == 0x5d && !first {
                self.i += 1;
                break;
            }
            if c == 0x5d {
                self.i += 1;
                break;
            }
            first = false;
            let lo = self.class_atom()?;
            if self.peek() == Some(0x2d) && self.p.get(self.i + 1).is_some_and(|x| *x != 0x5d) {
                if let Node::Unit(a) = lo {
                    self.i += 1;
                    match self.class_atom()? {
                        Node::Unit(z) => {
                            if z < a {
                                return Err(());
                            }
                            ranges.push((a, z));
                            continue;
                        }
                        Node::Class(r, n) => {
                            ranges.push((a, a));
                            ranges.push((0x2d, 0x2d));
                            ranges.extend(if n { negate(&r) } else { r });
                            continue;
                        }
                        _ => return Err(()),
                    }
                }
            }
            match lo {
                Node::Unit(a) => ranges.push((a, a)),
                Node::Class(r, n) => ranges.extend(if n { negate(&r) } else { r }),
                _ => return Err(()),
            }
        }
        Ok(Node::Class(ranges, neg))
    }
    fn class_atom(&mut self) -> Result<Node, ()> {
        let c = self.peek().ok_or(())?;
        self.i += 1;
        if c == 0x5c { self.escape(true) } else { Ok(Node::Unit(c)) }
    }
}

impl Regex {
    fn new(pattern: &[u16], flags: &str) -> Result<Regex, ()> {
        let mut p = Parser { p: pattern, i: 0, groups: 0 };
        let node = p.alt()?;
        if p.i != pattern.len() {
            return Err(());
        }
        Ok(Regex { node, groups: p.groups, icase: flags.contains('i'), multiline: flags.contains('m'), dot_all: flags.contains('s') })
    }
    /// the first match: the whole match and each group
    fn search(&self, t: &[u16]) -> Option<Caps> {
        for start in 0..=t.len() {
            let mut caps: Caps = vec![None; self.groups + 1];
            let mut end = None;
            if start == 0 {
                STEPS.with(|x| x.set(0));
            }
            if self.m(&self.node, t, start, &mut caps, &mut |e, _| {
                end = Some(e);
                true
            }) {
                caps[0] = Some((start, end.unwrap()));
                return Some(caps);
            }
        }
        None
    }
    fn fold(&self, c: u16) -> u16 {
        if !self.icase {
            return c;
        }
        match char::from_u32(c as u32) {
            Some(x) => {
                let mut up = x.to_uppercase();
                match (up.next(), up.next()) {
                    (Some(u), None) if (u as u32) < 0x10000 && !((u as u32) < 128 && c >= 128) => u as u16,
                    _ => c,
                }
            }
            None => c,
        }
    }
    fn in_class(&self, r: &[(u16, u16)], neg: bool, c: u16) -> bool {
        let hit = |x: u16| r.iter().any(|(a, z)| *a <= x && x <= *z);
        let mut found = hit(c);
        if !found && self.icase {
            let f = self.fold(c);
            found = hit(f) || r.iter().any(|(a, z)| (*a..=*z).any(|x| self.fold(x) == f) && (z - a) < 512);
        }
        found != neg
    }
    fn word_at(t: &[u16], i: usize) -> bool {
        t.get(i).is_some_and(|c| WORD.iter().any(|(a, z)| a <= c && c <= z))
    }
    fn line_end(c: u16) -> bool {
        matches!(c, 0x0a | 0x0d | 0x2028 | 0x2029)
    }
    /// does node match at i, with k accepting where it ends
    fn m(&self, node: &Node, t: &[u16], i: usize, caps: &mut Caps, k: &mut dyn FnMut(usize, &mut Caps) -> bool) -> bool {
        // a pattern that backtracks without end gives up (no match)
        if STEPS.with(|x| {
            x.set(x.get() + 1);
            x.get() > 1_000_000
        }) {
            return false;
        }
        match node {
            Node::Unit(c) => i < t.len() && self.fold(t[i]) == self.fold(*c) && k(i + 1, caps),
            Node::Any => i < t.len() && (self.dot_all || !Self::line_end(t[i])) && k(i + 1, caps),
            Node::Class(r, neg) => i < t.len() && self.in_class(r, *neg, t[i]) && k(i + 1, caps),
            Node::Start => (i == 0 || (self.multiline && Self::line_end(t[i - 1]))) && k(i, caps),
            Node::End => (i == t.len() || (self.multiline && Self::line_end(t[i]))) && k(i, caps),
            Node::Word(want) => {
                let at = Self::word_at(t, i) != (i > 0 && Self::word_at(t, i - 1));
                at == *want && k(i, caps)
            }
            Node::Group(inner, g) => match g {
                None => self.m(inner, t, i, caps, k),
                Some(g) => {
                    let g = *g;
                    let old = caps[g];
                    if self.m(inner, t, i, caps, &mut |e, c: &mut Caps| {
                        let before = c[g];
                        c[g] = Some((i, e));
                        if k(e, c) {
                            return true;
                        }
                        c[g] = before;
                        false
                    }) {
                        return true;
                    }
                    caps[g] = old;
                    false
                }
            },
            Node::Look(inner, want, behind) => {
                let mut c2 = caps.clone();
                let hit = if *behind {
                    (0..=i).rev().any(|j| self.m(inner, t, j, &mut c2, &mut |e, _| e == i))
                } else {
                    self.m(inner, t, i, &mut c2, &mut |_, _| true)
                };
                if hit != *want {
                    return false;
                }
                if *want {
                    *caps = c2;
                }
                k(i, caps)
            }
            Node::Backref(g) => {
                let span = caps.get(*g).copied().flatten();
                match span {
                    None => k(i, caps),
                    Some((a, z)) => {
                        let w = z - a;
                        i + w <= t.len() && (0..w).all(|x| self.fold(t[a + x]) == self.fold(t[i + x])) && k(i + w, caps)
                    }
                }
            }
            Node::Alt(options) => options.iter().any(|o| self.m(o, t, i, caps, k)),
            Node::Seq(items) => self.seq(items, t, i, caps, k),
            Node::Repeat(inner, lo, hi, greedy) => self.rep(inner, *lo, *hi, *greedy, 0, t, i, usize::MAX, caps, k),
        }
    }
    fn seq(&self, items: &[Node], t: &[u16], i: usize, caps: &mut Caps, k: &mut dyn FnMut(usize, &mut Caps) -> bool) -> bool {
        match items.split_first() {
            None => k(i, caps),
            Some((x, rest)) => self.m(x, t, i, caps, &mut |e, c: &mut Caps| self.seq(rest, t, e, c, k)),
        }
    }
    #[allow(clippy::too_many_arguments)]
    fn rep(&self, inner: &Node, lo: usize, hi: usize, greedy: bool, count: usize, t: &[u16], i: usize, last: usize, caps: &mut Caps, k: &mut dyn FnMut(usize, &mut Caps) -> bool) -> bool {
        // an empty iteration ends the loop (as in JavaScript)
        if count > lo && i == last {
            return false;
        }
        let more = |s: &Self, caps: &mut Caps, k: &mut dyn FnMut(usize, &mut Caps) -> bool| {
            count < hi && s.m(inner, t, i, caps, &mut |e, c: &mut Caps| s.rep(inner, lo, hi, greedy, count + 1, t, e, i, c, k))
        };
        if count < lo {
            return more(self, caps, k);
        }
        if greedy {
            more(self, caps, k) || k(i, caps)
        } else {
            k(i, caps) || more(self, caps, k)
        }
    }
}

